window.QUIZ={"course":{"code":"CS105","key":"cs105.quiz.v1","prof":"★ question from the slides","sub":"A–D, Yes/No and True/False · code tracing · one chapter per lecture · progress saved in this browser","exams":[{"name":"Midterm","date":"2026-11-16","when":"week 8 (date TBA)","scope":"Weeks 1–7: Java basics, classes, UML, copy constructors, inheritance, exceptions, file I/O (scope to confirm)"}]},"built":"2026-11-15","chapters":[{"id":"w01","title":"W1 · Java basics (ch. 1–3)","short":"W1 Basics","exam":"Midterm","date":"2026-11-16","w":0.8,"topics":["Java platform & bytecode","Types & casting","Operators & expressions","Strings","Branching","Loops"],"n":34},{"id":"w02","title":"W2 · Defining classes I (ch. 4)","short":"W2 Classes I","exam":"Midterm","date":"2026-11-16","w":1.0,"topics":["Classes & objects","Methods & parameters","this & constructors","Overloading","Encapsulation & access","equals, toString & testing"],"n":33},{"id":"w03","title":"W3 · Defining classes II (ch. 5)","short":"W3 Classes II","exam":"Midterm","date":"2026-11-16","w":1.1,"topics":["Static methods & variables","References & memory","Math & printf","Class parameters","Wrapper classes","Privacy leaks & null","Packages & import"],"n":35},{"id":"w04","title":"W4 · UML & patterns (ch. 12)","short":"W4 UML","exam":"Midterm","date":"2026-11-16","w":0.9,"topics":["UML diagrams","Class diagram notation","Singleton","Container, Adaptor & MVC","Sorting pattern","Merge & quick sort"],"n":34},{"id":"w05","title":"W5 · Copy constructors","short":"W5 Copy","exam":"Midterm","date":"2026-11-16","w":1.1,"topics":["Copy constructors","Class parameters","Aliasing & ==","Privacy leaks","Mutable vs immutable","Deep vs shallow copy"],"n":30},{"id":"w06","title":"W6 · Inheritance (ch. 7)","short":"W6 Inherit","exam":"Midterm","date":"2026-11-16","w":1.2,"topics":["Types & is-a","Overriding vs overloading","super & this constructors","Object, equals & getClass","Inheritance basics","Access modifiers"],"n":34},{"id":"w07","title":"W7 · Exception handling (ch. 9)","short":"W7 Except","exam":"Midterm","date":"2026-11-16","w":1.1,"topics":["Scanner & InputMismatchException","try-catch-finally flow","Custom exception classes","Checked vs unchecked","throws & catch-or-declare","Catch order"],"n":33},{"id":"w08","title":"W7 · File I/O (ch. 10)","short":"W7 File I/O","exam":"Midterm","date":"2026-11-16","w":1.0,"topics":["Streams & file types","Writing with PrintWriter","Appending","Reading with Scanner","Reading with BufferedReader","I/O exceptions & paths"],"n":31}],"questions":[{"id":"w01-001","chapter":"w01","topic":"Java platform & bytecode","type":"yn","q":"Is Java bytecode a machine language (like x86-64 or ARM)?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. Bytecode is an intermediate instruction set for the JVM; the JVM interprets it or JIT-compiles it into the host CPU's real machine code at run time.","source":"slides 13–14 (instructor Q&A)","study":"01-java-basics.md — 2. Compiling and running: bytecode, JVM, JIT, class loader (slides 11–21)","origin":"professor"},{"id":"w01-002","chapter":"w01","topic":"Types & casting","type":"yn","q":"Is this statement correct?\nint i = 5.5;","options":["Yes","No"],"answer":1,"fixed":false,"why":"No — a double value cannot be stored in an int variable without a cast. int i = (int)5.5; is the correct form (i becomes 5). Verified with javac.","source":"slide 45 (instructor mini-exercise)","study":"01-java-basics.md — 6. Assignment compatibility and type casting (slides 34–35, 43–45)","origin":"professor"},{"id":"w01-003","chapter":"w01","topic":"Java platform & bytecode","type":"yn","q":"Can the JVM's JIT compiler turn Java bytecode into the host CPU's real machine code while the program runs?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. That is exactly what JIT (Just-In-Time) compilation does — which is why bytecode itself is not machine code.","source":"slides 14, 16","study":"01-java-basics.md — 2. Compiling and running: bytecode, JVM, JIT, class loader (slides 11–21)","origin":"practice","twin":"w01-001"},{"id":"w01-004","chapter":"w01","topic":"Java platform & bytecode","type":"yn","q":"Is Java bytecode tied to one CPU, so that a .class file compiled on Windows/x86 cannot run on a Mac/ARM?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. Bytecode is for the (fictitious) Java Virtual Machine, so any computer with a JVM can run it — that is Java's portability.","source":"slide 12","study":"01-java-basics.md — 2. Compiling and running: bytecode, JVM, JIT, class loader (slides 11–21)","origin":"practice","twin":"w01-001"},{"id":"w01-005","chapter":"w01","topic":"Types & casting","type":"yn","q":"Is this statement correct?\nint i = (int)5.5;","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes — the explicit cast truncates 5.5 to 5, so the value fits in an int.","source":"slide 45","study":"01-java-basics.md — 6. Assignment compatibility and type casting (slides 34–35, 43–45)","origin":"practice","twin":"w01-002"},{"id":"w01-006","chapter":"w01","topic":"Types & casting","type":"yn","q":"Is this statement correct?\ndouble d = 5;","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes — int is to the left of double in the widening order, so Java converts automatically (type coercion).","source":"slides 34, 44","study":"01-java-basics.md — 6. Assignment compatibility and type casting (slides 34–35, 43–45)","origin":"practice","twin":"w01-002"},{"id":"w01-007","chapter":"w01","topic":"Types & casting","type":"yn","q":"Is this statement correct?\nlong big = 3.0;","options":["Yes","No"],"answer":1,"fixed":false,"why":"No — 3.0 is a double literal and double is to the right of long, so an explicit cast (long) is required. javac reports a lossy conversion.","source":"slide 35","study":"01-java-basics.md — 6. Assignment compatibility and type casting (slides 34–35, 43–45)","origin":"practice","twin":"w01-002"},{"id":"w01-008","chapter":"w01","topic":"Java platform & bytecode","type":"mcq","q":"What file does the command javac FirstProgram.java produce?","options":["FirstProgram.class","FirstProgram.exe","FirstProgram.byte","FirstProgram.jvm"],"answer":0,"fixed":false,"why":"javac writes the bytecode to a file named after the class with the .class extension.","source":"slide 18","study":"01-java-basics.md — 2. Compiling and running: bytecode, JVM, JIT, class loader (slides 11–21)","origin":"practice"},{"id":"w01-009","chapter":"w01","topic":"Java platform & bytecode","type":"mcq","q":"Which command runs the compiled program whose main method is in class FirstProgram?","options":["java FirstProgram.class","java FirstProgram","javac FirstProgram","java FirstProgram.java -run"],"answer":1,"fixed":false,"why":"The run command takes the class name only, without .java or .class. javac is the compiler, not the launcher.","source":"slide 19","study":"01-java-basics.md — 2. Compiling and running: bytecode, JVM, JIT, class loader (slides 11–21)","origin":"practice"},{"id":"w01-010","chapter":"w01","topic":"Java platform & bytecode","type":"mcq","q":"Which Java component connects the bytecode of all the classes a program needs (the job a linker does in C++)?","options":["The JIT compiler","The interpreter","The class loader","javap"],"answer":2,"fixed":false,"why":"Slide 17: the class loader connects the classes' bytecode; in C++ the corresponding program is the linker. javap is only a disassembler.","source":"slide 17","study":"01-java-basics.md — 2. Compiling and running: bytecode, JVM, JIT, class loader (slides 11–21)","origin":"practice"},{"id":"w01-011","chapter":"w01","topic":"Java platform & bytecode","type":"tf","q":"Java bytecode is stack-based: its instructions push and pop values on an operand stack.","options":["True","False"],"answer":0,"fixed":false,"why":"True (slide 15). e.g. return a + b; becomes iload_1, iload_2, iadd, ireturn.","source":"slide 15 (instructor Q&A)","study":"01-java-basics.md — 2. Compiling and running: bytecode, JVM, JIT, class loader (slides 11–21)","origin":"practice"},{"id":"w01-012","chapter":"w01","topic":"Types & casting","type":"mcq","q":"Which declaration does NOT compile without an explicit cast?","options":["double d = 5;","long n = 7;","char c = 'A'; int k = c;","float f = 2.5;"],"answer":3,"fixed":false,"why":"2.5 is a double literal and float is to the left of double in the widening order, so (float) or 2.5f is needed. The others widen automatically. Verified with javac.","source":"slide 35","study":"01-java-basics.md — 6. Assignment compatibility and type casting (slides 34–35, 43–45)","origin":"practice"},{"id":"w01-013","chapter":"w01","topic":"Types & casting","type":"mcq","q":"What does this print?\ndouble d = 9.99;\nSystem.out.println((int) d + \" \" + (int) -2.7);","options":["9 -2","10 -3","9 -3","10 -2"],"answer":0,"fixed":false,"why":"A cast from floating point to int truncates toward zero; it never rounds. Ran on JDK 26.","source":"slide 44","study":"01-java-basics.md — 6. Assignment compatibility and type casting (slides 34–35, 43–45)","origin":"practice"},{"id":"w01-014","chapter":"w01","topic":"Types & casting","type":"tf","q":"In Java, boolean b = 1; compiles, because 1 means true.","options":["True","False"],"answer":1,"fixed":false,"why":"False. int and boolean are never assignment-compatible in Java, in either direction (javac error).","source":"slide 35","study":"01-java-basics.md — 6. Assignment compatibility and type casting (slides 34–35, 43–45)","origin":"practice"},{"id":"w01-015","chapter":"w01","topic":"Operators & expressions","type":"mcq","q":"What does this print?\nint n = 5;\nint r = 3 * n++ + --n;\nSystem.out.println(r + \" \" + n);","options":["21 5","20 5","18 4","20 6"],"answer":1,"fixed":false,"why":"n++ yields 5 (n becomes 6), then --n makes n 5 and yields 5: 3*5 + 5 = 20, final n = 5. Ran on JDK 26.","source":"slides 47–49","study":"01-java-basics.md — 8. Increment and decrement (slides 47–49)","origin":"practice"},{"id":"w01-016","chapter":"w01","topic":"Operators & expressions","type":"mcq","q":"What does this print?\nint n = 2;\nint result = 2 * (n++);\nSystem.out.println(result + \" \" + n);","options":["6 3","4 2","4 3","6 2"],"answer":2,"fixed":false,"why":"Postfix uses the old value (2) in the expression, then increments: result 4, n 3. 6 would be the prefix ++n version.","source":"slides 48–49","study":"01-java-basics.md — 8. Increment and decrement (slides 47–49)","origin":"practice"},{"id":"w01-017","chapter":"w01","topic":"Operators & expressions","type":"mcq","q":"What does this print?\nSystem.out.println(17/5 + \" \" + 17%5 + \" \" + 17.0/5 + \" \" + (double)(17/5));","options":["3 2 3.4 3.4","3.4 2 3.4 3.0","3 3 3.4 3.0","3 2 3.4 3.0"],"answer":3,"fixed":false,"why":"17/5 is integer division (3), remainder 2, 17.0/5 is 3.4, and (double)(17/5) casts AFTER the int division, giving 3.0.","source":"slides 41–43","study":"01-java-basics.md — 7. Arithmetic: precedence, division, % (slides 38–42, 76)","origin":"practice"},{"id":"w01-018","chapter":"w01","topic":"Operators & expressions","type":"mcq","q":"What is the final value of c?\nint c = 10;\nc += 5;\nc *= 2 + 1;\nc %= 7;","options":["3","1","31","0"],"answer":0,"fixed":false,"why":"c = 15; then c *= (2 + 1) gives 45 (the whole right side is evaluated first); 45 % 7 = 3.","source":"slide 33","study":"01-java-basics.md — 5. Variables, assignment, constants (slides 25–37)","origin":"practice"},{"id":"w01-019","chapter":"w01","topic":"Operators & expressions","type":"mcq","q":"What does this print?\nint y = 2;\nint z = y++ + y++;\nSystem.out.println(z + \" \" + y);","options":["4 4","5 4","6 4","5 3"],"answer":1,"fixed":false,"why":"First y++ gives 2 (y→3), second gives 3 (y→4): z = 5, y = 4. Ran on JDK 26.","source":"slide 48","study":"01-java-basics.md — 8. Increment and decrement (slides 47–49)","origin":"practice"},{"id":"w01-020","chapter":"w01","topic":"Operators & expressions","type":"tf","q":"With int a = 3, b = 8; the expression a > 5 && b / 0 > 1 throws an ArithmeticException.","options":["True","False"],"answer":1,"fixed":false,"why":"False. a > 5 is false, so && short-circuits and never evaluates b / 0; the result is simply false. Ran on JDK 26.","source":"slides 74–75","study":"01-java-basics.md — 11. Flow of control: branching (slides 65–76)","origin":"practice"},{"id":"w01-021","chapter":"w01","topic":"Strings","type":"mcq","q":"What does this print?\nString s = \"Hello World\";\nSystem.out.println(s.substring(3,7) + \"|\" + s.indexOf(\"o\") + \"|\" + s.lastIndexOf(\"o\"));","options":["lo Wo|4|7","lo W|5|8","lo W|4|7","llo |4|7"],"answer":2,"fixed":false,"why":"substring(3,7) takes indexes 3,4,5,6 = \"lo W\" (end excluded); the first 'o' is at index 4, the last at 7.","source":"slides 57–59, 61","study":"01-java-basics.md — 9. Strings (slides 50–61, Display 1.4 and 1.5)","origin":"practice"},{"id":"w01-022","chapter":"w01","topic":"Strings","type":"mcq","q":"What does this print?\nSystem.out.println(1 + 2 + \"3\" + 4 + 5);","options":["12345","15","339","3345"],"answer":3,"fixed":false,"why":"Left to right: 1 + 2 = 3 (numbers), then \"3\" turns everything after it into concatenation: \"33\" + 4 + 5 = \"3345\".","source":"slide 51","study":"01-java-basics.md — 9. Strings (slides 50–61, Display 1.4 and 1.5)","origin":"practice"},{"id":"w01-023","chapter":"w01","topic":"Strings","type":"mcq","q":"What does this print?\nString a = \"java\";\nString b = new String(\"java\");\nSystem.out.println((a == b) + \" \" + a.equals(b));","options":["false true","true true","true false","false false"],"answer":0,"fixed":false,"why":"== compares references: b is a separate object, so false. equals compares the characters: true.","source":"slide 73","study":"01-java-basics.md — 11. Flow of control: branching (slides 65–76)","origin":"practice"},{"id":"w01-024","chapter":"w01","topic":"Strings","type":"mcq","q":"What does \"AbcdefG\".substring(2, 5) return?","options":["\"bcde\"","\"cde\"","\"cdef\"","\"bcd\""],"answer":1,"fixed":false,"why":"Start index 2 is included, end index 5 is excluded: characters at 2, 3, 4.","source":"slide 58","study":"01-java-basics.md — 9. Strings (slides 50–61, Display 1.4 and 1.5)","origin":"practice"},{"id":"w01-025","chapter":"w01","topic":"Strings","type":"tf","q":"\"Zebra\".compareTo(\"apple\") returns a negative number.","options":["True","False"],"answer":0,"fixed":false,"why":"True. compareTo uses Unicode order, where all uppercase letters come before all lowercase letters, so \"Zebra\" comes first.","source":"slide 60","study":"01-java-basics.md — 9. Strings (slides 50–61, Display 1.4 and 1.5)","origin":"practice"},{"id":"w01-026","chapter":"w01","topic":"Strings","type":"mcq","q":"What does this print?\nString s = \"Java is fun.\";\nSystem.out.println(s.charAt(5) + \" \" + s.indexOf(\"is\") + \" \" + s.substring(8));","options":["s 5 fun.","i 6 fun.","i 5 fun.","i 5 un."],"answer":2,"fixed":false,"why":"Indexes start at 0 and blanks count (slide 61): index 5 is 'i', \"is\" starts at 5, substring(8) is \"fun.\".","source":"slides 57, 61","study":"01-java-basics.md — 9. Strings (slides 50–61, Display 1.4 and 1.5)","origin":"practice"},{"id":"w01-027","chapter":"w01","topic":"Branching","type":"mcq","q":"What does this print?\nint x = 7;\nswitch (x % 3) {\n  case 0: System.out.print(\"A\");\n  case 1: System.out.print(\"B\");\n  case 2: System.out.print(\"C\"); break;\n  default: System.out.print(\"D\");\n}","options":["B","BCD","ABC","BC"],"answer":3,"fixed":false,"why":"7 % 3 = 1, so execution starts at case 1; with no break it falls through to case 2, which breaks.","source":"slide 69","study":"01-java-basics.md — 11. Flow of control: branching (slides 65–76)","origin":"practice"},{"id":"w01-028","chapter":"w01","topic":"Branching","type":"mcq","q":"What does this print?\nint x = 10;\nif (x > 5)\n  if (x > 20) System.out.println(\"big\");\n  else System.out.println(\"medium\");","options":["medium","big","nothing is printed","big then medium"],"answer":0,"fixed":false,"why":"An else belongs to the nearest unmatched if (x > 20). x > 5 is true, x > 20 is false, so the else runs.","source":"slides 66–68","study":"01-java-basics.md — 11. Flow of control: branching (slides 65–76)","origin":"practice"},{"id":"w01-029","chapter":"w01","topic":"Branching","type":"mcq","q":"int m = 4;\nint p = m > 3 ? m * 2 : m - 1;\nWhat is p?","options":["3","8","4","7"],"answer":1,"fixed":false,"why":"The condition m > 3 is true, so the conditional operator yields the first expression, m * 2 = 8.","source":"slide 70","study":"01-java-basics.md — 11. Flow of control: branching (slides 65–76)","origin":"practice"},{"id":"w01-030","chapter":"w01","topic":"Loops","type":"mcq","q":"What does this print?\nint count = 0;\nfor (int i = 1; i <= 3; i++)\n  for (int j = i; j <= 3; j++)\n    count++;\nSystem.out.println(count);","options":["9","3","6","5"],"answer":2,"fixed":false,"why":"The inner loop runs 3, 2, then 1 times: 3 + 2 + 1 = 6.","source":"slide 80","study":"01-java-basics.md — 12. Loops (slides 77–82)","origin":"practice"},{"id":"w01-031","chapter":"w01","topic":"Loops","type":"mcq","q":"What does this print?\nint k = 10;\ndo { k -= 4; } while (k > 5);\nSystem.out.println(k);","options":["6","-2","10","2"],"answer":3,"fixed":false,"why":"10 → 6 (6 > 5, repeat) → 2 (stop). The do-while body always runs at least once.","source":"slide 79","study":"01-java-basics.md — 12. Loops (slides 77–82)","origin":"practice"},{"id":"w01-032","chapter":"w01","topic":"Loops","type":"mcq","q":"What does this print?\nouter:\nfor (int i = 1; i <= 3; i++)\n  for (int j = 1; j <= 3; j++) {\n    if (i * j == 4) break outer;\n    System.out.print(i * j + \" \");\n  }","options":["1 2 3 2 ","1 2 3 2 6 3 6 9 ","1 2 3 ","1 2 3 2 3 6 9 "],"answer":0,"fixed":false,"why":"Row i=1 prints 1 2 3; row i=2 prints 2, then i*j = 4 triggers break outer, which leaves BOTH loops.","source":"slide 81","study":"01-java-basics.md — 12. Loops (slides 77–82)","origin":"practice"},{"id":"w01-033","chapter":"w01","topic":"Loops","type":"mcq","q":"Which statement ends the whole program immediately, not just the current loop?","options":["break;","System.exit(0);","return;  (inside a loop in a helper method)","continue;"],"answer":1,"fixed":false,"why":"System.exit ends the program; break only leaves the innermost loop/switch and return only leaves the current method.","source":"slide 82","study":"01-java-basics.md — 12. Loops (slides 77–82)","origin":"practice"},{"id":"w01-034","chapter":"w01","topic":"Loops","type":"tf","q":"The body of a while loop always executes at least once.","options":["True","False"],"answer":1,"fixed":false,"why":"False. while tests the condition first, so the body may run zero times. It is the do-while body that always runs at least once.","source":"slides 78–79","study":"01-java-basics.md — 12. Loops (slides 77–82)","origin":"practice"},{"id":"w02-001","chapter":"w02","topic":"Classes & objects","type":"mcq","q":"What is a class?","options":["A defined type that includes both data and method (code) specifications","A variable that stores one object's data","A method that creates objects","A file that stores bytecode for one method"],"answer":0,"fixed":false,"why":"His slide 47 answer: a class is a defined type with both data and method specifications. A variable of that type is the object.","source":"slide 47 (instructor question)","study":"02-defining-classes-i.md — 11. Instructor's in-class questions (slides 47–53) — learn his answers","origin":"professor"},{"id":"w02-002","chapter":"w02","topic":"Classes & objects","type":"mcq","q":"What is an object?","options":["The blueprint that lists a type's fields and methods","A variable of a class type — an instance or implementation of the class","A primitive value such as an int","A method that returns a value"],"answer":1,"fixed":false,"why":"Slide 48: an object is a variable of a class type, also called an instance or implementation. The blueprint is the class.","source":"slide 48 (instructor question)","study":"02-defining-classes-i.md — 11. Instructor's in-class questions (slides 47–53) — learn his answers","origin":"professor"},{"id":"w02-003","chapter":"w02","topic":"Classes & objects","type":"mcq","q":"What is the difference between a class and an object?","options":["An object is a specification; the class holds the data","There is none — the words are interchangeable","The class is only a specification; objects hold specific data for each instance","Classes contain methods, objects never do"],"answer":2,"fixed":false,"why":"Slide 49: the class is only the specification (blueprint); each object holds its own data (the building).","source":"slide 49 (instructor question)","study":"02-defining-classes-i.md — 11. Instructor's in-class questions (slides 47–53) — learn his answers","origin":"professor"},{"id":"w02-004","chapter":"w02","topic":"Classes & objects","type":"mcq","q":"What is an instance variable?","options":["A data item declared inside one method","A parameter of a constructor","A variable shared by all programs","A data item defined in a class, available to all methods of the class"],"answer":3,"fixed":false,"why":"Slide 50: a defined data item of a class, available to all its methods. A data item inside a method is a local variable.","source":"slide 50 (instructor question)","study":"02-defining-classes-i.md — 11. Instructor's in-class questions (slides 47–53) — learn his answers","origin":"professor"},{"id":"w02-005","chapter":"w02","topic":"Methods & parameters","type":"mcq","q":"What is a local variable?","options":["A data item defined in a method, only available within that method","A data item of a class, available to all its methods","A private instance variable","A variable that is automatically initialised to 0"],"answer":0,"fixed":false,"why":"Slide 51: a defined data item of a method, only available within the method. Local variables are NOT automatically initialised.","source":"slide 51 (instructor question)","study":"02-defining-classes-i.md — 11. Instructor's in-class questions (slides 47–53) — learn his answers","origin":"professor"},{"id":"w02-006","chapter":"w02","topic":"Classes & objects","type":"mcq","q":"What is the new operator?","options":["It declares a variable of a class type","It creates the object and associates it with its variable name","It calls the main method","It copies an existing object"],"answer":1,"fixed":false,"why":"Slide 52: new creates the object (in memory) and associates it with the variable. ClassName x; alone only declares the variable.","source":"slide 52 (instructor question)","study":"02-defining-classes-i.md — 11. Instructor's in-class questions (slides 47–53) — learn his answers","origin":"professor"},{"id":"w02-007","chapter":"w02","topic":"this & constructors","type":"mcq","q":"What is the this keyword?","options":["The name of the class being defined","A reference to the previously created object","Within a method, an explicit name for the current (calling) object","A keyword that makes a variable constant"],"answer":2,"fixed":false,"why":"Slide 53: within a method, this is an explicit name for the calling object.","source":"slide 53 (instructor question)","study":"02-defining-classes-i.md — 11. Instructor's in-class questions (slides 47–53) — learn his answers","origin":"professor"},{"id":"w02-008","chapter":"w02","topic":"Methods & parameters","type":"mcq","q":"What does this print?\nstatic void bump(int v) { v = v + 10; }\n...\nint x = 5;\nbump(x);\nSystem.out.println(x);","options":["15","10","0","5"],"answer":3,"fixed":false,"why":"Call-by-value: v gets a copy of 5; changing v does not change x. Ran on JDK 26.","source":"slides 33, 35","study":"02-defining-classes-i.md — 5. Parameters and call-by-value (slides 30–41)","origin":"practice"},{"id":"w02-009","chapter":"w02","topic":"Methods & parameters","type":"mcq","q":"In the slides' Bill class, computeFee(3, 48) does: minutesWorked = 3*60 + 48; quarterHours = minutesWorked/15; return quarterHours*RATE; with RATE = 150.00. What is returned?","options":["2250.0","2280.0","1650.0","2268.0"],"answer":0,"fixed":false,"why":"228 minutes / 15 = 15 (integer division drops the partial quarter), 15 × 150.0 = 2250.0. 1650.0 would be 2 h 48 min — the slide's sample dialogue misprints the hours.","source":"slides 37, 40","study":"02-defining-classes-i.md — 5. Parameters and call-by-value (slides 30–41)","origin":"practice"},{"id":"w02-010","chapter":"w02","topic":"Methods & parameters","type":"yn","q":"Will this compile inside one method?\n{ int y = 1; }\n{ String y = \"ok\"; }","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. The first y goes out of scope at its closing brace, so the name may be reused. (Slide 29 overstates the rule; only redeclaring while the first is still in scope is an error.)","source":"slide 29 (see Errata)","study":"02-defining-classes-i.md — 4. Local variables, blocks, no globals (slides 27–29)","origin":"practice"},{"id":"w02-011","chapter":"w02","topic":"Methods & parameters","type":"yn","q":"Will this method compile?\nvoid m() { int k; System.out.println(k); }","options":["Yes","No"],"answer":1,"fixed":false,"why":"No — local variables are not automatically initialised; javac reports 'variable k might not have been initialized'.","source":"slide 68","study":"02-defining-classes-i.md — 4. Local variables, blocks, no globals (slides 27–29)","origin":"practice"},{"id":"w02-012","chapter":"w02","topic":"Methods & parameters","type":"tf","q":"Java has global variables, declared outside any class.","options":["True","False"],"answer":1,"fixed":false,"why":"False — slide 28: Java has no global variables. Everything lives inside a class.","source":"slide 28","study":"02-defining-classes-i.md — 4. Local variables, blocks, no globals (slides 27–29)","origin":"practice"},{"id":"w02-013","chapter":"w02","topic":"Classes & objects","type":"mcq","q":"What does this print?\nclass Counter { private int n; Counter(){ n = 0; } Counter(int s){ n = s; }\n  void inc(){ n++; } int get(){ return n; } }\n...\nCounter c1 = new Counter(), c2 = new Counter(5);\nc1.inc(); c2.inc(); c2.inc();\nSystem.out.println(c1.get() + \" \" + c2.get());","options":["2 7","1 7","1 6","3 3"],"answer":1,"fixed":false,"why":"Each object has its own n: c1 goes 0 → 1, c2 goes 5 → 7. Ran on JDK 26.","source":"slides 7, 63–64","study":"02-defining-classes-i.md — 1. Class and object (slides 2–7)","origin":"practice"},{"id":"w02-014","chapter":"w02","topic":"Classes & objects","type":"mcq","q":"Continuing: c2.get() is 7.\nCounter c3 = c2;\nc3.inc();\nSystem.out.println(c2.get() + \" \" + (c3 == c2));","options":["7 false","8 false","8 true","7 true"],"answer":2,"fixed":false,"why":"c3 = c2 copies the reference, not the object: both names refer to one object, so c2 sees the increment and == is true.","source":"slides 9–10, 46","study":"02-defining-classes-i.md — 2. Contents of a class definition (slides 8–13)","origin":"practice"},{"id":"w02-015","chapter":"w02","topic":"this & constructors","type":"mcq","q":"What does this print?\nclass Pt { int x; String name; boolean ok; }\n...\nPt p = new Pt();\nSystem.out.println(p.x + \" \" + p.name + \" \" + p.ok);","options":["0 \"\" false","compile error: fields not initialised","null null null","0 null false"],"answer":3,"fixed":false,"why":"Instance variables get defaults: numbers 0, class types null, boolean false (only LOCAL variables must be initialised).","source":"slide 68","study":"02-defining-classes-i.md — 10. Constructors (slides 63–69)","origin":"practice"},{"id":"w02-016","chapter":"w02","topic":"this & constructors","type":"mcq","q":"class Person {\n  private String name;\n  public Person(String name) { name = name; }\n  public String getName() { return name; }\n}\nWhat does new Person(\"Ana\").getName() return?","options":["null","\"Ana\"","\"name\"","It does not compile"],"answer":0,"fixed":false,"why":"Inside the constructor both names mean the parameter, so the field is never set and keeps its default null. Fix: this.name = name;","source":"slides 42–43","study":"02-defining-classes-i.md — 6. The `this` keyword (slides 42–44, 53, 66)","origin":"practice"},{"id":"w02-017","chapter":"w02","topic":"this & constructors","type":"mcq","q":"class Box {\n  int w, h;\n  Box() { this(3); }\n  Box(int w) { this(w, w * 2); }\n  Box(int w, int h) { this.w = w; this.h = h; }\n}\nAfter Box b = new Box(); what are b.w and b.h?","options":["0 and 0","3 and 6","3 and 0","3 and 3"],"answer":1,"fixed":false,"why":"Box() → Box(3) → Box(3, 6), which stores both fields. One constructor may call another with this(...).","source":"slide 65","study":"02-defining-classes-i.md — 10. Constructors (slides 63–69)","origin":"practice"},{"id":"w02-018","chapter":"w02","topic":"this & constructors","type":"yn","q":"class Car { private String m; public Car(String m) { this.m = m; } }\nIs Car c = new Car(); a compile error?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. Once a class defines any constructor, Java does not supply the default no-argument one. javac: 'constructor Car cannot be applied to given types'.","source":"slide 67","study":"02-defining-classes-i.md — 10. Constructors (slides 63–69)","origin":"practice"},{"id":"w02-019","chapter":"w02","topic":"this & constructors","type":"tf","q":"A constructor has no return type at all — not even void.","options":["True","False"],"answer":0,"fixed":false,"why":"True. A constructor has no return type, not even void. Writing void turns it into an ordinary method that happens to share the class name.","source":"slide 63","study":"02-defining-classes-i.md — 10. Constructors (slides 63–69)","origin":"practice"},{"id":"w02-020","chapter":"w02","topic":"this & constructors","type":"mcq","q":"When does Java automatically provide a no-argument (default) constructor?","options":["Always, in addition to any constructors you write","Only when all instance variables are private","Only when the class defines no constructors at all","Only when the class has a main method"],"answer":2,"fixed":false,"why":"Slide 67: if you include even one constructor, Java will not provide the default one.","source":"slide 67","study":"02-defining-classes-i.md — 10. Constructors (slides 63–69)","origin":"practice"},{"id":"w02-021","chapter":"w02","topic":"Overloading","type":"mcq","q":"A method's signature consists of:","options":["its name and its return type","its name, parameter list and return type","its return type and parameter list","its name and its parameter list (number, types, order)"],"answer":3,"fixed":false,"why":"Slides 58, 61: the signature is the name plus the parameter types; the return type is not part of it.","source":"slides 58, 61","study":"02-defining-classes-i.md — 9. Overloading (slides 58–62)","origin":"practice"},{"id":"w02-022","chapter":"w02","topic":"Overloading","type":"yn","q":"Will this class compile?\nclass R { int f(int a) { return a; }\n          double f(int b) { return b; } }","options":["Yes","No"],"answer":1,"fixed":false,"why":"No — same name and same parameter types means the same signature; a different return type is not enough ('method f(int) is already defined').","source":"slide 61","study":"02-defining-classes-i.md — 9. Overloading (slides 58–62)","origin":"practice"},{"id":"w02-023","chapter":"w02","topic":"Overloading","type":"yn","q":"Will this class compile?\nclass P { void p(int a) { }\n          void p(int a, int b) { } }","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes — the parameter lists differ in number, so these are two valid overloads.","source":"slide 58","study":"02-defining-classes-i.md — 9. Overloading (slides 58–62)","origin":"practice"},{"id":"w02-024","chapter":"w02","topic":"Overloading","type":"mcq","q":"static String f(int a) { return \"int\"; }\nstatic String f(double a) { return \"double\"; }\nWhat does f(3) + \" \" + f(3.0) + \" \" + f('c') give?","options":["int double int","int double double","int int int","compile error: f('c') is ambiguous"],"answer":0,"fixed":false,"why":"Exact matches for 3 and 3.0; 'c' has no char version, so Java widens char to the nearest type, int. Ran on JDK 26.","source":"slides 34, 60","study":"02-defining-classes-i.md — 9. Overloading (slides 58–62)","origin":"practice"},{"id":"w02-025","chapter":"w02","topic":"Overloading","type":"yn","q":"static void h(int a, double b) { }\nstatic void h(double a, int b) { }\nDoes the call h(1, 2); compile?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No — both overloads need one int→double conversion, neither is better, so javac reports 'reference to h is ambiguous' (slide 60).","source":"slide 60","study":"02-defining-classes-i.md — 9. Overloading (slides 58–62)","origin":"practice"},{"id":"w02-026","chapter":"w02","topic":"Overloading","type":"tf","q":"Java lets you overload operators such as + for your own classes, as C++ does.","options":["True","False"],"answer":1,"fixed":false,"why":"False — slide 62: Java does not permit operator overloading; use ordinary methods.","source":"slide 62","study":"02-defining-classes-i.md — 9. Overloading (slides 58–62)","origin":"practice"},{"id":"w02-027","chapter":"w02","topic":"Encapsulation & access","type":"mcq","q":"Which of these is NOT one of the three steps of encapsulation on slide 75?","options":["Declare data members private","Make all methods private","Provide public getters and setters","Validate data inside the setters"],"answer":1,"fixed":false,"why":"The three steps are: private data, public getters/setters, validation in setters. Most methods stay public — only helpers are private.","source":"slides 54, 75","study":"02-defining-classes-i.md — 13. Encapsulation and information hiding (slides 72–81)","origin":"practice"},{"id":"w02-028","chapter":"w02","topic":"Encapsulation & access","type":"mcq","q":"A member must be usable inside its own package and by subclasses in other packages, but not by unrelated classes in other packages. Which modifier?","options":["private","default (no modifier)","protected","public"],"answer":2,"fixed":false,"why":"Slide 79 table: protected = same class, same package, and subclasses anywhere. Default stops at the package boundary; public allows everyone.","source":"slides 77–79","study":"02-defining-classes-i.md — 13. Encapsulation and information hiding (slides 72–81)","origin":"practice"},{"id":"w02-029","chapter":"w02","topic":"Encapsulation & access","type":"yn","q":"class Acc { private int bal; }\nclass Other { void m() { Acc a = new Acc(); a.bal = 5; } }\nDoes javac reject class Other with an access error?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes — private members cannot be accessed by name outside their class ('bal has private access in Acc'). Use a public mutator.","source":"slide 54","study":"02-defining-classes-i.md — 8. public / private, accessors, mutators, pre/postconditions (slides 54–57)","origin":"practice"},{"id":"w02-030","chapter":"w02","topic":"Encapsulation & access","type":"mcq","q":"class Temp { private double c;\n  boolean setC(double v) { if (v < -273.15) return false; c = v; return true; }\n  double getC() { return c; } }\nTemp t = new Temp();\nSystem.out.println(t.setC(-300) + \" \" + t.getC() + \" \" + t.setC(25) + \" \" + t.getC());","options":["false -300.0 true 25.0","true -300.0 true 25.0","false 0.0 true 0.0","false 0.0 true 25.0"],"answer":3,"fixed":false,"why":"The mutator rejects -300 and leaves c at its default 0.0, then accepts 25. This is the 'mutator returns boolean' pattern of slide 56.","source":"slide 56","study":"02-defining-classes-i.md — 8. public / private, accessors, mutators, pre/postconditions (slides 54–57)","origin":"practice"},{"id":"w02-031","chapter":"w02","topic":"equals, toString & testing","type":"mcq","q":"Pair has fields a, b, an equals(Pair o) comparing both fields, and toString() returning \"(a, b)\".\nPair p = new Pair(1, 2), q = new Pair(1, 2);\nSystem.out.println((p == q) + \" \" + p.equals(q) + \" \" + p);","options":["false true (1, 2)","true true (1, 2)","false true Pair@1b6d3586","false false (1, 2)"],"answer":0,"fixed":false,"why":"== compares references (two objects → false); equals compares fields (true); println uses toString automatically.","source":"slide 46","study":"02-defining-classes-i.md — 7. equals and toString (slides 45–46)","origin":"practice"},{"id":"w02-032","chapter":"w02","topic":"equals, toString & testing","type":"mcq","q":"A simplified version of a method that is not finished yet, returning a fixed value so that other methods can be tested, is called a:","options":["driver program","stub","accessor","precondition"],"answer":1,"fixed":false,"why":"Slide 70: that is a stub. A driver program is the program whose only purpose is to test a method.","source":"slide 70","study":"02-defining-classes-i.md — 12. Testing methods (slides 70–71)","origin":"practice"},{"id":"w02-033","chapter":"w02","topic":"equals, toString & testing","type":"tf","q":"The postcondition of a method states what will be true after the method runs, provided the precondition held when it was called.","options":["True","False"],"answer":0,"fixed":false,"why":"True — slide 57. The precondition states what is assumed true when the method is called.","source":"slide 57","study":"02-defining-classes-i.md — 8. public / private, accessors, mutators, pre/postconditions (slides 54–57)","origin":"practice"},{"id":"w03-001","chapter":"w03","topic":"Static methods & variables","type":"mcq","q":"Q1 (in-class): What is a static method?","options":["A method whose body cannot be overridden or changed after compilation","A method associated with the class itself rather than with any specific object of the class","A method that can be called only once for each object","A method that cannot take any parameters"],"answer":1,"fixed":false,"why":"A static method belongs to the class and is called with the class name (e.g. Math.random()). 'Cannot be changed' describes final, not static.","source":"slide 20 (Q1)","study":"03-defining-classes-ii.md — 2. Static methods (slides 12–22)","origin":"professor"},{"id":"w03-002","chapter":"w03","topic":"Static methods & variables","type":"yn","q":"Q2 (in-class): Can a static method use the 'this' keyword?","options":["Yes","No"],"answer":1,"fixed":true,"why":"No: there is no object associated with a static method, so 'this' has nothing to refer to.","source":"slide 21 (Q2)","study":"03-defining-classes-ii.md — 2. Static methods (slides 12–22)","origin":"professor"},{"id":"w03-003","chapter":"w03","topic":"Static methods & variables","type":"yn","q":"Q3 (in-class): Can you directly call a non-static method from within a static method, without specifying an object?","options":["Yes","No"],"answer":1,"fixed":true,"why":"No: a non-static method needs a host object. Use objectName.method() instead.","source":"slide 22 (Q3)","study":"03-defining-classes-ii.md — 2. Static methods (slides 12–22)","origin":"professor"},{"id":"w03-004","chapter":"w03","topic":"References & memory","type":"mcq","q":"Q4 (in-class): When a class variable is created in Java, what is stored in the variable?","options":["The actual object information","The instance variables only","The instance methods only","A memory address which identifies the object storage location"],"answer":3,"fixed":true,"why":"A class-type variable holds only a reference (memory address); the object itself lives elsewhere in memory.","source":"slides 57–58 (Q4)","study":"03-defining-classes-ii.md — 7. References (slides 49–58)","origin":"professor"},{"id":"w03-005","chapter":"w03","topic":"Math & printf","type":"mcq","q":"In-class question: Is System.out a class or an object?","options":["A class in the java.lang package","A static method of the System class","A package that contains println","An object: a static field of the System class, an instance of PrintStream"],"answer":3,"fixed":false,"why":"out is a static member field of System; its type is PrintStream. System is the class, println is the method.","source":"slide 5","study":"03-defining-classes-ii.md — 1. Recap: System.out, print, println, printf (slides 3–11)","origin":"professor"},{"id":"w03-006","chapter":"w03","topic":"Static methods & variables","type":"yn","q":"Can a static method read a static variable of its own class directly, without naming an object?","options":["Yes","No"],"answer":0,"fixed":true,"why":"Yes: static variables belong to the class, so a static method may use them; only instance variables are off limits.","source":"slide 23","study":"03-defining-classes-ii.md — 3. Static variables and constants (slides 23–25)","origin":"practice","twin":"w03-002"},{"id":"w03-007","chapter":"w03","topic":"Static methods & variables","type":"yn","q":"Inside a static method, can you call a non-static method of the class if you write obj.method() on an object obj of that class?","options":["Yes","No"],"answer":0,"fixed":true,"why":"Yes: the restriction is only on calling it without a calling object; naming an object provides one.","source":"slide 22 (A3) · slide 19 (temperatureObject.toString())","study":"03-defining-classes-ii.md — 2. Static methods (slides 12–22)","origin":"practice","twin":"w03-003"},{"id":"w03-008","chapter":"w03","topic":"References & memory","type":"mcq","q":"After ToyClass v2 = v1; (where v1 refers to an object), what does v2 contain?","options":["The same memory address as v1","A new copy of the object that v1 names","null until v2 is constructed","Only the instance variables of v1"],"answer":0,"fixed":false,"why":"Assignment copies the reference, so both variables name the same object (Display 5.13). No copy of the object is made.","source":"slides 51, 54–56","study":"03-defining-classes-ii.md — 7. References (slides 49–58)","origin":"practice","twin":"w03-004"},{"id":"w03-009","chapter":"w03","topic":"Static methods & variables","type":"mcq","q":"What does this print?\nclass Counter {\n    static int count = 0;\n    int id;\n    Counter() { count++; id = count; }\n}\n// in main:\nCounter a = new Counter(), b = new Counter(), c = new Counter();\nSystem.out.println(a.id + \" \" + c.id + \" \" + Counter.count);","options":["1 1 3","3 3 3","1 3 3","1 2 3"],"answer":2,"fixed":false,"why":"count is shared (one copy), id is per object: a.id was set to 1, c.id to 3, and count ends at 3. 3 3 3 would be true only if id were static.","source":"slides 23–24 · verified with java","study":"03-defining-classes-ii.md — 3. Static variables and constants (slides 23–25)","origin":"practice"},{"id":"w03-010","chapter":"w03","topic":"Class parameters","type":"mcq","q":"What does this print?\nstatic void moveAway(Point p) { p = new Point(9, 9); }\nstatic void shift(Point p) { p.x++; }\n// in main:\nPoint a = new Point(1, 1);\nmoveAway(a);\nshift(a);\nSystem.out.println(a.x + \" \" + a.y);","options":["9 9","2 1","10 9","1 1"],"answer":1,"fixed":false,"why":"moveAway only changes its local copy of the address; shift changes the shared object. 10 9 assumes the new object replaced a.","source":"slide 60 NOTE · verified with java","study":"03-defining-classes-ii.md — 8. Class parameters: call-by-value of an address (slides 59–70)","origin":"practice"},{"id":"w03-011","chapter":"w03","topic":"Class parameters","type":"mcq","q":"What does this print?\nstatic void change(int n, ToyClass t) { n = 99; t.set(\"Changed\", 99); }\n// in main:\nint n = 5;\nToyClass t = new ToyClass(\"Toy\", 1);\nchange(n, t);\nSystem.out.println(n + \" \" + t);   // toString: name + \" \" + number","options":["99 Changed 99","5 Toy 1","99 Toy 1","5 Changed 99"],"answer":3,"fixed":false,"why":"A primitive argument cannot be changed; the object's instance variables can (Display 5.16).","source":"slides 66–68 · verified with java","study":"03-defining-classes-ii.md — 8. Class parameters: call-by-value of an address (slides 59–70)","origin":"practice"},{"id":"w03-012","chapter":"w03","topic":"References & memory","type":"mcq","q":"What does this print? (equals compares name and number)\nToyClass t1 = new ToyClass(\"A\", 1);\nToyClass t2 = new ToyClass(\"A\", 1);\nToyClass t3 = t1;\nSystem.out.println((t1 == t2) + \" \" + t1.equals(t2) + \" \" + (t1 == t3));","options":["false true true","true true true","false false true","true false true"],"answer":0,"fixed":false,"why":"== compares addresses: t1 and t2 are different objects with equal data; t3 holds t1's address.","source":"slide 71 · verified with java","study":"03-defining-classes-ii.md — 9. `=` and `==` with objects; `null`; anonymous objects (slides 71–74)","origin":"practice"},{"id":"w03-013","chapter":"w03","topic":"References & memory","type":"mcq","q":"What does this print?\nToyClass t1 = new ToyClass(\"A\", 1);\nToyClass t3 = t1;\nt3.set(\"B\", 2);\nSystem.out.println(t1);   // toString: name + \" \" + number","options":["A 1","A 1 then B 2","B 2","Compile error: t1 was not changed"],"answer":2,"fixed":false,"why":"t1 and t3 name the same object, so a change through t3 is visible through t1.","source":"slides 54–56 · verified with java","study":"03-defining-classes-ii.md — 7. References (slides 49–58)","origin":"practice"},{"id":"w03-014","chapter":"w03","topic":"Wrapper classes","type":"mcq","q":"What does this print?\nSystem.out.println(Character.toUpperCase('a') + 1);","options":["B","66","A1","98"],"answer":1,"fixed":false,"why":"toUpperCase returns the char 'A' (code 65); char + int is an int, so 66 is printed. 'A1' needs a String on the left.","source":"slides 42–44 · verified with java","study":"03-defining-classes-ii.md — 5. Wrapper classes, boxing, unboxing (slides 34–44)","origin":"practice"},{"id":"w03-015","chapter":"w03","topic":"Wrapper classes","type":"mcq","q":"What does this print?\nInteger i1 = 1000, i2 = 1000;\nSystem.out.println((i1 == i2) + \" \" + i1.equals(i2));","options":["true true","false false","true false","false true"],"answer":3,"fixed":false,"why":"i1 and i2 are two Integer objects, so == compares addresses (false); equals compares values (true).","source":"slides 37, 71 · verified with java","study":"03-defining-classes-ii.md — 5. Wrapper classes, boxing, unboxing (slides 34–44)","origin":"practice"},{"id":"w03-016","chapter":"w03","topic":"Math & printf","type":"mcq","q":"What does this print?\nSystem.out.println(Math.round(3.6) + Math.ceil(3.2));","options":["8.0","8","7.0","7"],"answer":0,"fixed":false,"why":"round(3.6) is the long 4 and ceil(3.2) is the double 4.0; long + double = double 8.0.","source":"slides 30–31 · verified with java","study":"03-defining-classes-ii.md — 4. The Math class (slides 26–33)","origin":"practice"},{"id":"w03-017","chapter":"w03","topic":"Wrapper classes","type":"mcq","q":"What does this print?\nSystem.out.println(Integer.parseInt(\"101\", 2) + Integer.parseInt(\"10\"));","options":["10110","111","15","NumberFormatException"],"answer":2,"fixed":false,"why":"\"101\" in base 2 is 5, plus 10 gives 15. Both results are ints, so they are added, not concatenated.","source":"slide 39 · verified with java","study":"03-defining-classes-ii.md — 5. Wrapper classes, boxing, unboxing (slides 34–44)","origin":"practice"},{"id":"w03-018","chapter":"w03","topic":"Math & printf","type":"mcq","q":"What does this print?\nSystem.out.printf(\"%6.2f|\", 3.14159);","options":["3.14|","  3.14|","3.141590|","    3.14|"],"answer":1,"fixed":false,"why":"Width 6 with 2 decimals: \"3.14\" is 4 characters, so 2 spaces of padding on the left.","source":"slide 10 · verified with java","study":"03-defining-classes-ii.md — 1. Recap: System.out, print, println, printf (slides 3–11)","origin":"practice"},{"id":"w03-019","chapter":"w03","topic":"Math & printf","type":"tf","q":"Math.ceil(3.2) returns 4.0, a value of type double.","options":["True","False"],"answer":0,"fixed":true,"why":"ceil and floor return double; you need a cast to get an int. Math.round(double) is the one that returns long.","source":"slides 31–32","study":"03-defining-classes-ii.md — 4. The Math class (slides 26–33)","origin":"practice"},{"id":"w03-020","chapter":"w03","topic":"Wrapper classes","type":"tf","q":"Double.MIN_VALUE is the most negative value a double can hold.","options":["True","False"],"answer":1,"fixed":true,"why":"Double.MIN_VALUE is the smallest POSITIVE double (4.9E-324); the most negative is -Double.MAX_VALUE.","source":"slide 38 · verified with java","study":"03-defining-classes-ii.md — 5. Wrapper classes, boxing, unboxing (slides 34–44)","origin":"practice"},{"id":"w03-021","chapter":"w03","topic":"Wrapper classes","type":"mcq","q":"What happens?\nInteger z = null;\nint k = z;","options":["k becomes 0","A compile-time error","k becomes null","A NullPointerException at run time"],"answer":3,"fixed":false,"why":"Auto-unboxing calls z.intValue() on null. It compiles fine, then fails at run time.","source":"slides 37, 73 · verified with java","study":"03-defining-classes-ii.md — 5. Wrapper classes, boxing, unboxing (slides 34–44)","origin":"practice"},{"id":"w03-022","chapter":"w03","topic":"Privacy leaks & null","type":"mcq","q":"What does this print?\nclass Wallet {\n    private int[] coins = {1, 2, 3};\n    public int[] getCoins() { return coins; }\n    public int total() { int s = 0; for (int c : coins) s += c; return s; }\n}\n// in main:\nWallet w = new Wallet();\nw.getCoins()[0] = 100;\nSystem.out.println(w.total());","options":["105","6","100","Compile error: coins is private"],"answer":0,"fixed":false,"why":"getCoins returns the array's address, so main changes the private array (privacy leak). private only hides the name, not the object.","source":"slide 75 · verified with java","study":"03-defining-classes-ii.md — 10. Privacy leaks (slide 75)","origin":"practice"},{"id":"w03-023","chapter":"w03","topic":"Packages & import","type":"tf","q":"import java.util.*; also imports the classes of the subpackage java.util.concurrent.","options":["True","False"],"answer":1,"fixed":true,"why":"A wildcard import never includes subpackages; each package needs its own import.","source":"slide 82","study":"03-defining-classes-ii.md — 11. Packages and import (slides 76–86)","origin":"practice"},{"id":"w03-024","chapter":"w03","topic":"Packages & import","type":"mcq","q":"In a Java source file that has both, which must come first?","options":["The import statements","The class declaration","The package statement","Either order is allowed"],"answer":2,"fixed":false,"why":"Only blank lines and comments may precede the package statement; imports come after it.","source":"slides 76, 78","study":"03-defining-classes-ii.md — 11. Packages and import (slides 76–86)","origin":"practice"},{"id":"w03-025","chapter":"w03","topic":"Class parameters","type":"yn","q":"Can a method change the value of a primitive-type variable that is passed to it as an argument?","options":["Yes","No"],"answer":1,"fixed":true,"why":"No: the parameter is a local copy of the value (call-by-value).","source":"slide 66","study":"03-defining-classes-ii.md — 8. Class parameters: call-by-value of an address (slides 59–70)","origin":"practice"},{"id":"w03-026","chapter":"w03","topic":"Class parameters","type":"yn","q":"Can a method change the instance variables of an object that is passed to it as an argument?","options":["Yes","No"],"answer":0,"fixed":true,"why":"Yes: the parameter receives the object's address, so it names the same object.","source":"slides 60, 66","study":"03-defining-classes-ii.md — 8. Class parameters: call-by-value of an address (slides 59–70)","origin":"practice"},{"id":"w03-027","chapter":"w03","topic":"Static methods & variables","type":"mcq","q":"Why does this class not compile?\npublic class Box {\n    private int size;\n    public static void grow() { size++; }\n}","options":["size must be public to be changed","A static method cannot use the instance variable size","++ cannot be applied to a private variable","A static method must return a value"],"answer":1,"fixed":false,"why":"grow has no calling object (no this), so it cannot refer to an instance variable. javac: 'non-static variable size cannot be referenced from a static context'.","source":"slide 14 · verified with javac","study":"03-defining-classes-ii.md — 2. Static methods (slides 12–22)","origin":"practice"},{"id":"w03-028","chapter":"w03","topic":"Wrapper classes","type":"tf","q":"Wrapper classes such as Integer have a no-argument constructor.","options":["True","False"],"answer":1,"fixed":true,"why":"Unlike most classes, a wrapper class has no no-argument constructor; it always wraps a given value.","source":"slide 35","study":"03-defining-classes-ii.md — 5. Wrapper classes, boxing, unboxing (slides 34–44)","origin":"practice"},{"id":"w03-029","chapter":"w03","topic":"Static methods & variables","type":"tf","q":"A static variable that is not explicitly initialised gets a default value: 0 for numbers, false for boolean, null for class types.","options":["True","False"],"answer":0,"fixed":true,"why":"This is the automatic default initialisation, although the slides recommend explicit initialisation.","source":"slide 24","study":"03-defining-classes-ii.md — 3. Static variables and constants (slides 23–25)","origin":"practice"},{"id":"w03-030","chapter":"w03","topic":"Packages & import","type":"mcq","q":"Two packages both contain a class named Date. How do you use both in one program?","options":["Rename one of the classes","Import both with wildcards and Java picks the right one","It is impossible in one program","Use the fully qualified names, e.g. java.util.Date and java.sql.Date"],"answer":3,"fixed":false,"why":"Fully qualified names resolve name clashes; importing both by wildcard makes 'Date' ambiguous.","source":"slide 86","study":"03-defining-classes-ii.md — 11. Packages and import (slides 76–86)","origin":"practice"},{"id":"w03-031","chapter":"w03","topic":"Math & printf","type":"mcq","q":"What does Math.random() return?","options":["A pseudo-random double ≥ 0.0 and < 1.0","A random int between 0 and 100","A pseudo-random double ≥ 0.0 and ≤ 1.0","A truly random long"],"answer":0,"fixed":false,"why":"random() takes no arguments and returns a double in [0.0, 1.0); 1.0 itself is never returned.","source":"slide 33","study":"03-defining-classes-ii.md — 4. The Math class (slides 26–33)","origin":"practice"},{"id":"w03-032","chapter":"w03","topic":"Static methods & variables","type":"tf","q":"A static defined constant such as public static final int BIRTH_YEAR = 1954; may safely be public.","options":["True","False"],"answer":0,"fixed":true,"why":"Because final prevents changes, a static constant can be public; other static variables should be private.","source":"slide 25","study":"03-defining-classes-ii.md — 3. Static variables and constants (slides 23–25)","origin":"practice"},{"id":"w03-033","chapter":"w03","topic":"Packages & import","type":"mcq","q":"You set the CLASSPATH variable but leave out the current directory (.). What can happen?","options":["Nothing: . is always searched first","Only java.lang classes stop working","Java may not find the .class files of your own program","The compiler adds . automatically"],"answer":2,"fixed":false,"why":"If CLASSPATH is set, . must be one of its entries, otherwise classes in the current directory are not found.","source":"slide 84","study":"03-defining-classes-ii.md — 11. Packages and import (slides 76–86)","origin":"practice"},{"id":"w03-034","chapter":"w03","topic":"Privacy leaks & null","type":"mcq","q":"Which getter avoids a privacy leak for private int[] coins?","options":["return coins;","return coins.clone();","return this.coins;","return (int[]) coins;"],"answer":1,"fixed":false,"why":"Only clone() hands out a new array; the other three all return the address of the private array.","source":"slide 75","study":"03-defining-classes-ii.md — 10. Privacy leaks (slide 75)","origin":"practice"},{"id":"w03-035","chapter":"w03","topic":"Privacy leaks & null","type":"yn","q":"Does a NullPointerException occur when you test if (obj == null) on a variable that holds null?","options":["Yes","No"],"answer":1,"fixed":true,"why":"No: == only compares the reference with null. The exception happens when you call a method on null.","source":"slides 72–73","study":"03-defining-classes-ii.md — 9. `=` and `==` with objects; `null`; anonymous objects (slides 71–74)","origin":"practice"},{"id":"w04-001","chapter":"w04","topic":"UML diagrams","type":"mcq","q":"Which UML diagram shows the interactions between actors (users or external systems) and a software system?","options":["Class diagram","State diagram","Use case diagram","Activity diagram"],"answer":2,"fixed":false,"why":"Use case diagrams show actors (stick figures) and the use cases (ovals) they interact with; activity diagrams show workflow steps.","source":"slides 5, 7","study":"04-uml-and-patterns.md — 2. The five UML diagram types (slides 5–10)","origin":"practice"},{"id":"w04-002","chapter":"w04","topic":"UML diagrams","type":"mcq","q":"Which UML diagram shows the activities (workflow) involved in a software process, with forks and decisions?","options":["Activity diagram","Sequence diagram","Use case diagram","Class diagram"],"answer":0,"fixed":false,"why":"The activity diagram (Receive Order → Fill Order / Send Invoice …) shows the steps of a process.","source":"slides 5–6","study":"04-uml-and-patterns.md — 2. The five UML diagram types (slides 5–10)","origin":"practice"},{"id":"w04-003","chapter":"w04","topic":"UML diagrams","type":"mcq","q":"Which UML diagram shows time-ordered messages between objects along vertical lifelines?","options":["State diagram","Activity diagram","Use case diagram","Sequence diagram"],"answer":3,"fixed":false,"why":"In a sequence diagram time flows downwards and arrows are messages between lifelines (Customer → EShopWebsite → Payment Gateway).","source":"slides 5, 8","study":"04-uml-and-patterns.md — 2. The five UML diagram types (slides 5–10)","origin":"practice"},{"id":"w04-004","chapter":"w04","topic":"UML diagrams","type":"mcq","q":"Which UML diagram shows how the status of a system changes in response to internal and external events?","options":["Class diagram","State diagram","Sequence diagram","Activity diagram"],"answer":1,"fixed":false,"why":"A state diagram has states (Login, Search products, Checkout …) and transitions triggered by events/conditions.","source":"slides 5, 9","study":"04-uml-and-patterns.md — 2. The five UML diagram types (slides 5–10)","origin":"practice"},{"id":"w04-005","chapter":"w04","topic":"UML diagrams","type":"mcq","q":"Who released an early version of UML in 1996?","options":["James Gosling, Bill Joy and Mike Sheridan","Gamma, Helm, Johnson and Vlissides","Grady Booch, Ivar Jacobson and James Rumbaugh","Walter Savitch and Frank Carrano"],"answer":2,"fixed":false,"why":"The 'three amigos' Booch, Jacobson and Rumbaugh (the slide misspells Grady as 'Brady'). Gamma et al. wrote the design-patterns book; Gosling created Java.","source":"slide 4","study":"04-uml-and-patterns.md — 1. UML and patterns: definitions (slides 2–4, 17–18)","origin":"practice"},{"id":"w04-006","chapter":"w04","topic":"UML diagrams","type":"tf","q":"Today the UML standard is maintained and certified by the Object Management Group (OMG).","options":["True","False"],"answer":0,"fixed":true,"why":"Slide 4 states this; UML was standardised through the OMG.","source":"slide 4","study":"04-uml-and-patterns.md — 1. UML and patterns: definitions (slides 2–4, 17–18)","origin":"practice"},{"id":"w04-007","chapter":"w04","topic":"Class diagram notation","type":"mcq","q":"In a UML class diagram a method is listed as # erase() : void. What is the Java header?","options":["protected void erase()","private void erase()","public void erase()","void erase()  (package access)"],"answer":0,"fixed":false,"why":"# means protected. - is private, + is public, ~ is package access (no modifier).","source":"slides 12, 14","study":"04-uml-and-patterns.md — 3. Class diagram notation (slides 11–16)","origin":"practice"},{"id":"w04-008","chapter":"w04","topic":"Class diagram notation","type":"mcq","q":"What does the symbol ~ mean in front of a member in a UML class diagram?","options":["Protected access","Static member","Private access","Package access"],"answer":3,"fixed":false,"why":"+ public, - private, # protected, ~ package. Static members are underlined, not marked with ~.","source":"slide 12","study":"04-uml-and-patterns.md — 3. Class diagram notation (slides 11–16)","origin":"practice"},{"id":"w04-009","chapter":"w04","topic":"Class diagram notation","type":"mcq","q":"Which UML entry correctly describes a private instance variable balance of type double?","options":["+ balance : double","- balance : double","- double balance","private double : balance"],"answer":1,"fixed":false,"why":"UML data format is visibility name : type, and - means private. 'double balance' is Java order, not UML.","source":"slides 12–14","study":"04-uml-and-patterns.md — 3. Class diagram notation (slides 11–16)","origin":"practice"},{"id":"w04-010","chapter":"w04","topic":"Class diagram notation","type":"mcq","q":"Which UML entry correctly describes public void deposit(double amount)?","options":["+ void deposit(double amount)","- deposit(double amount) : void","+ deposit(double amount) : void","+ deposit : void(double amount)"],"answer":2,"fixed":false,"why":"Methods: visibility name(parameter list) : return type, with + for public.","source":"slide 13","study":"04-uml-and-patterns.md — 3. Class diagram notation (slides 11–16)","origin":"practice"},{"id":"w04-011","chapter":"w04","topic":"Class diagram notation","type":"tf","q":"A UML class diagram must list every instance variable and method of the class.","options":["True","False"],"answer":1,"fixed":true,"why":"A class diagram need not be complete; members not needed for the analysis are left out and shown by an ellipsis (...).","source":"slide 15","study":"04-uml-and-patterns.md — 3. Class diagram notation (slides 11–16)","origin":"practice"},{"id":"w04-012","chapter":"w04","topic":"Class diagram notation","type":"mcq","q":"In the online-shop class diagram (slide 10) a line with a hollow triangle runs from Customer to User. What does it mean?","options":["Customer is a subclass of User (Customer extends User)","User contains a list of Customers","Customer calls the methods of User","User is a subclass of Customer"],"answer":0,"fixed":false,"why":"A hollow triangle arrowhead is generalisation (inheritance), pointing at the superclass.","source":"slide 10","study":"04-uml-and-patterns.md — 2. The five UML diagram types (slides 5–10)","origin":"practice"},{"id":"w04-013","chapter":"w04","topic":"Class diagram notation","type":"mcq","q":"In slide 10, Order is joined to Shipping info by a line with a filled diamond at the Order end and multiplicity 1 at both ends. What relationship is that?","options":["Inheritance: Shipping info extends Order","Package grouping of the two classes","A dependency with no fields involved","Composition: each Order owns exactly one Shipping info"],"answer":3,"fixed":false,"why":"A filled (black) diamond is composition, the strongest whole–part relation; the diamond sits at the 'whole' end.","source":"slide 10","study":"04-uml-and-patterns.md — 2. The five UML diagram types (slides 5–10)","origin":"practice"},{"id":"w04-014","chapter":"w04","topic":"UML diagrams","type":"yn","q":"Is UML tied to the Java language?","options":["Yes","No"],"answer":1,"fixed":true,"why":"No: UML and patterns are design tools usable with any OOP language (slide 2).","source":"slide 2","study":"04-uml-and-patterns.md — 1. UML and patterns: definitions (slides 2–4, 17–18)","origin":"practice"},{"id":"w04-015","chapter":"w04","topic":"Class diagram notation","type":"yn","q":"Can one class diagram show both inheritance and composition relationships at the same time?","options":["Yes","No"],"answer":0,"fixed":true,"why":"Yes: slide 10 shows Customer–User inheritance and Customer/Order/Shipping-info compositions in one diagram.","source":"slide 10","study":"04-uml-and-patterns.md — 2. The five UML diagram types (slides 5–10)","origin":"practice"},{"id":"w04-016","chapter":"w04","topic":"Singleton","type":"mcq","q":"What prevents other classes from creating a second instance of a Singleton?","options":["Its getInstance method is final","Its constructor is private","Its instance variable is public static","The class is declared abstract"],"answer":1,"fixed":false,"why":"With a private constructor, only the class itself can call new; everyone else must use the public static getInstance().","source":"slide 19","study":"04-uml-and-patterns.md — 4. Singleton pattern (slide 19 — instructor addition)","origin":"practice"},{"id":"w04-017","chapter":"w04","topic":"Singleton","type":"mcq","q":"What does this print?\nclass Single {\n    private static Single inst;\n    static int made = 0;\n    private Single() { made++; }\n    public static Single getInstance() {\n        if (inst == null) inst = new Single();\n        return inst;\n    }\n}\n// in main:\nSingle s1 = Single.getInstance(), s2 = Single.getInstance();\nSystem.out.println((s1 == s2) + \" \" + Single.made);","options":["false 2","true 2","true 1","false 1"],"answer":2,"fixed":false,"why":"The object is created only on the first call; the second call returns the same reference, so == is true and the constructor ran once.","source":"slide 19 · verified with java","study":"04-uml-and-patterns.md — 4. Singleton pattern (slide 19 — instructor addition)","origin":"practice"},{"id":"w04-018","chapter":"w04","topic":"Singleton","type":"tf","q":"Overusing the Singleton pattern can make code hard to test and tightly coupled.","options":["True","False"],"answer":0,"fixed":true,"why":"Slide 19 lists difficulty with testing, tight coupling and possible performance bottlenecks.","source":"slide 19","study":"04-uml-and-patterns.md — 4. Singleton pattern (slide 19 — instructor addition)","origin":"practice"},{"id":"w04-019","chapter":"w04","topic":"Singleton","type":"mcq","q":"Which is a typical use of the Singleton pattern given on the slides?","options":["A logger or a database connection","A sorting algorithm","Each item in a shopping cart","A temporary array in merge sort"],"answer":0,"fixed":false,"why":"A Singleton suits things the system needs exactly one of, such as a logger or a DB connection.","source":"slide 19","study":"04-uml-and-patterns.md — 4. Singleton pattern (slide 19 — instructor addition)","origin":"practice"},{"id":"w04-020","chapter":"w04","topic":"Container, Adaptor & MVC","type":"mcq","q":"In the Container–Iterator pattern, what is the iterator for an array?","options":["The array's length","The array's first element","The String class","The array index"],"answer":3,"fixed":false,"why":"An iterator is anything that cycles through all items of a container; for an array that is the index.","source":"slide 20","study":"04-uml-and-patterns.md — 5. Container–Iterator pattern (slide 20)","origin":"practice"},{"id":"w04-021","chapter":"w04","topic":"Container, Adaptor & MVC","type":"mcq","q":"Building a stack class on top of an array, without changing the array, is an example of which pattern?","options":["Singleton","Adaptor","Model-View-Controller","Container-Iterator"],"answer":1,"fixed":false,"why":"The Adaptor pattern adds a new interface (push/pop) to an existing class without changing it.","source":"slide 21","study":"04-uml-and-patterns.md — 6. Adaptor pattern (slide 21)","origin":"practice"},{"id":"w04-022","chapter":"w04","topic":"Container, Adaptor & MVC","type":"mcq","q":"In the Model-View-Controller pattern, which part relays commands from the user (input) to the Model?","options":["The View","The Model itself","The Controller","The Iterator"],"answer":2,"fixed":false,"why":"Controller = input; View = output (a picture of the Model's state); Model = the heart of the application.","source":"slide 22","study":"04-uml-and-patterns.md — 7. Model–View–Controller (slides 22–26)","origin":"practice"},{"id":"w04-023","chapter":"w04","topic":"Container, Adaptor & MVC","type":"mcq","q":"In MVC (Display 12.4), which part notifies the View that it must update?","options":["The Model","The Controller","The user","The View notifies itself"],"answer":0,"fixed":false,"why":"The Model notifies the View (update()) whenever its state changes; the Controller manipulates the Model.","source":"slides 24, 26","study":"04-uml-and-patterns.md — 7. Model–View–Controller (slides 22–26)","origin":"practice"},{"id":"w04-024","chapter":"w04","topic":"Container, Adaptor & MVC","type":"tf","q":"The Model-View-Controller pattern can only be used for GUI applications.","options":["True","False"],"answer":1,"fixed":true,"why":"Any application can be made to fit MVC; it is particularly well suited to GUIs.","source":"slide 25","study":"04-uml-and-patterns.md — 7. Model–View–Controller (slides 22–26)","origin":"practice"},{"id":"w04-025","chapter":"w04","topic":"Sorting pattern","type":"mcq","q":"In the divide-and-conquer sorting pattern, what does sort do when end - begin >= 1?","options":["join, then split, then sort once","sort the whole interval, then split it","split and join only; no recursion","split, sort the left part, sort the right part, then join"],"answer":3,"fixed":false,"why":"Display 12.5: splitPoint = split(...); sort(begin, splitPoint); sort(splitPoint + 1, end); join(...).","source":"slide 30","study":"04-uml-and-patterns.md — 8. The divide-and-conquer sorting pattern (slides 27–30, 43)","origin":"practice"},{"id":"w04-026","chapter":"w04","topic":"Merge & quick sort","type":"mcq","q":"In merge sort, which method is simple and which is complicated?","options":["split is complicated, join is simple","split is simple, join is complicated","both are complicated","join does nothing"],"answer":1,"fixed":false,"why":"Merge sort's split just returns the midpoint; the merging in join does the work. Quick sort is the reverse.","source":"slides 31–32","study":"04-uml-and-patterns.md — 9. Merge sort (slides 31–36)","origin":"practice"},{"id":"w04-027","chapter":"w04","topic":"Merge & quick sort","type":"mcq","q":"What does the join method of quick sort (as on the slides) do?","options":["Merges two sorted halves with a temp array","Swaps the first and last elements","Nothing","Calls split again"],"answer":2,"fixed":false,"why":"After quick sort's split, every element left of the splitting value is ≤ every element right of it, so join has nothing to do.","source":"slides 39, 42, 45","study":"04-uml-and-patterns.md — 10. Quick sort (slides 37–42, 44–45)","origin":"practice"},{"id":"w04-028","chapter":"w04","topic":"Merge & quick sort","type":"mcq","q":"Using the slides' QuickSort.split (splitting value = a[begin]), what are the return value and the array after split(a, 0, 3) on a = {4, 1, 3, 2}?","options":["3 and {1, 3, 2, 4}","0 and {4, 1, 3, 2}","3 and {1, 2, 3, 4}","1 and {1, 4, 3, 2}"],"answer":0,"fixed":false,"why":"4 is the splitting value; 1, 3, 2 are all ≤ 4 and go to the front in order; 4 goes to index 3. The parts are not sorted by split.","source":"slides 40–41 · verified with java","study":"04-uml-and-patterns.md — 10. Quick sort (slides 37–42, 44–45)","origin":"practice"},{"id":"w04-029","chapter":"w04","topic":"Merge & quick sort","type":"mcq","q":"The slides' merge sort runs on the 10-element demo array. How many times is join called?","options":["10","5","19","9"],"answer":3,"fixed":false,"why":"Each join merges two lists into one, and we go from 10 one-element lists to 1 list: n − 1 = 9 joins. 19 is the number of sort calls.","source":"slides 33–36 · verified with java","study":"04-uml-and-patterns.md — 9. Merge sort (slides 31–36)","origin":"practice"},{"id":"w04-030","chapter":"w04","topic":"Merge & quick sort","type":"mcq","q":"What happens if the slide's QuickSort.sort (which recurses on sort(a, begin, splitPoint)) is called on {5.0, 5.0}?","options":["It returns {5.0, 5.0} correctly","Infinite recursion ending in a StackOverflowError","ArrayIndexOutOfBoundsException","It returns {0.0, 5.0}"],"answer":1,"fixed":false,"why":"split returns 1 (= end), so sort(a, 0, 1) calls itself with the same interval forever. Fix: sort(a, begin, splitPoint - 1).","source":"slide 40 · Errata · verified with java","study":"04-uml-and-patterns.md — 11. Errata","origin":"practice"},{"id":"w04-031","chapter":"w04","topic":"Merge & quick sort","type":"mcq","q":"Why can quick sort's worst case be slower than merge sort's?","options":["Its join method is more complicated","It needs a temporary array at every level","Its split may divide the array into very unequal parts","It only works on arrays of even length"],"answer":2,"fixed":false,"why":"Merge sort always halves the array; quick sort's split depends on the splitting value and may give 0 and n−1 elements.","source":"slide 46","study":"04-uml-and-patterns.md — 10. Quick sort (slides 37–42, 44–45)","origin":"practice"},{"id":"w04-032","chapter":"w04","topic":"Sorting pattern","type":"yn","q":"As given on the slides (using <), does the sorting pattern sort into decreasing order?","options":["Yes","No"],"answer":1,"fixed":true,"why":"No: slide 43 restricts it to increasing order and types with <; replace < by a boolean compare method to generalise it.","source":"slide 43","study":"04-uml-and-patterns.md — 8. The divide-and-conquer sorting pattern (slides 27–30, 43)","origin":"practice"},{"id":"w04-033","chapter":"w04","topic":"Sorting pattern","type":"tf","q":"Design patterns are established best practices and blueprints, not specific lines of code or libraries to paste in.","options":["True","False"],"answer":0,"fixed":true,"why":"Slide 18 says exactly this; slide 47 adds that patterns are guides, not requirements.","source":"slides 18, 47","study":"04-uml-and-patterns.md — 1. UML and patterns: definitions (slides 2–4, 17–18)","origin":"practice"},{"id":"w04-034","chapter":"w04","topic":"Merge & quick sort","type":"mcq","q":"Merge sort on [53, 13, 43, 10] (slide 28): what are the two sorted halves just before the final join?","options":["[13, 53] and [10, 43]","[13, 43] and [10, 53]","[53, 13] and [43, 10]","[10, 13] and [43, 53]"],"answer":0,"fixed":false,"why":"Each half is sorted recursively first: [53, 13] → [13, 53] and [43, 10] → [10, 43]; the last join gives [10, 13, 43, 53].","source":"slide 28","study":"04-uml-and-patterns.md — 9. Merge sort (slides 31–36)","origin":"practice"},{"id":"w05-001","chapter":"w05","topic":"Copy constructors","type":"mcq","q":"What is a copy-constructor? (Dr. Oladejo's in-class question)","options":["A constructor that creates a separate, independent object that is an exact copy of the argument object, at a new memory address","A constructor that returns a reference to the argument object so both variables share it","A method inherited from Object that copies any object automatically","A constructor with no parameters that sets every field to its default value"],"answer":0,"fixed":false,"why":"Slide 25's answer: a separate, independent object with the same instance-variable values but a new memory address. Returning/sharing the same reference is aliasing, not copying.","source":"slide 25","study":"05-copy-constructors.md — 4. `=` and `==` with objects; privacy leaks (slides 16–18, 25)","origin":"professor"},{"id":"w05-002","chapter":"w05","topic":"Class parameters","type":"tf","q":"In Java, every parameter — including class-type parameters — is passed call-by-value.","options":["True","False"],"answer":0,"fixed":false,"why":"Slide 2: all parameters are call-by-value. For a class type the value copied is the reference, which is why it only looks like call-by-reference.","source":"slides 2–3","study":"05-copy-constructors.md — 1. Java is always call-by-value (slides 2–3, 9)","origin":"practice"},{"id":"w05-003","chapter":"w05","topic":"Class parameters","type":"mcq","q":"class ToyClass {\n  private String name; private int number;\n  ToyClass(String n, int k) { name = n; number = k; }\n  void set(String n, int k) { name = n; number = k; }\n  public String toString() { return name + \" \" + number; }\n}\nstatic void changer(ToyClass p) { p.set(\"Hot Shot\", 42); }\n// in main:\nToyClass anObject = new ToyClass(\"Mr. Cellophane\", 0);\nchanger(anObject);\nSystem.out.println(anObject);\nWhat is printed?","options":["Mr. Cellophane 0","Hot Shot 42","Mr. Hot Shot 42","null 0"],"answer":1,"fixed":false,"why":"The parameter holds the same address as anObject, so changing the object's fields is visible to the caller (Display 5.14). Slide 11 writes 'Mr. Hot Shot' but the code sets \"Hot Shot\".","source":"slides 4–8, verified with JDK 26","study":"05-copy-constructors.md — 2. Display 5.14 — `ToyClass.changer` (slides 4–8, 10)","origin":"practice"},{"id":"w05-004","chapter":"w05","topic":"Class parameters","type":"mcq","q":"class ToyClass2 {\n  private int number = 1;\n  public void tryToMakeEqual(int aNumber) { aNumber = this.number; }\n}\n// in main:\nint aNumber = 42;\nnew ToyClass2().tryToMakeEqual(aNumber);\nSystem.out.println(aNumber);\nWhat is printed?","options":["1","0","42","Compile error"],"answer":2,"fixed":false,"why":"A primitive argument cannot be changed by the method: only the local copy aNumber inside tryToMakeEqual becomes 1.","source":"slides 12–15 (Display 5.16), verified","study":"05-copy-constructors.md — 3. Display 5.16/5.17 — class type vs primitive argument (slides 12–15)","origin":"practice"},{"id":"w05-005","chapter":"w05","topic":"Class parameters","type":"mcq","q":"With ToyClass2 from Display 5.17 (makeEqual copies this.name and this.number INTO its parameter):\nobject1.set(\"Scorpius\", 1);\nobject2.set(\"John Crichton\", 2);\nobject1.makeEqual(object2);\nSystem.out.println(object2);\nWhat is printed?","options":["John Crichton 2","Scorpius 2","John Crichton 1","Scorpius 1"],"answer":3,"fixed":false,"why":"makeEqual writes object1's fields into the object named by the parameter, which is object2 itself — an argument of a class type can change.","source":"slides 12–15, verified","study":"05-copy-constructors.md — 3. Display 5.16/5.17 — class type vs primitive argument (slides 12–15)","origin":"practice"},{"id":"w05-006","chapter":"w05","topic":"Class parameters","type":"mcq","q":"class ToyClass {\n  private String name; private int number;\n  ToyClass(String n, int k) { name = n; number = k; }\n  void set(String n, int k) { name = n; number = k; }\n  public String toString() { return name + \" \" + number; }\n}\nstatic void reset(ToyClass t) { t = new ToyClass(\"Z\", 0); }\n// in main:\nToyClass t = new ToyClass(\"A\", 1);\nreset(t);\nSystem.out.println(t);\nWhat is printed?","options":["A 1","Z 0","null","Compile error"],"answer":0,"fixed":false,"why":"Assigning a new object to the parameter only changes the local copy of the address; the caller's variable still points to the original object.","source":"slide 3, verified","study":"05-copy-constructors.md — 1. Java is always call-by-value (slides 2–3, 9)","origin":"practice"},{"id":"w05-007","chapter":"w05","topic":"Aliasing & ==","type":"mcq","q":"class ToyClass {\n  private String name; private int number;\n  ToyClass(String n, int k) { name = n; number = k; }\n  void set(String n, int k) { name = n; number = k; }\n  public String toString() { return name + \" \" + number; }\n}\n// in main:\nToyClass t = new ToyClass(\"A\", 1);\nToyClass u = t;\nu.set(\"B\", 2);\nSystem.out.println(t + \" \" + (t == u));\nWhat is printed?","options":["A 1 false","B 2 true","A 1 true","B 2 false"],"answer":1,"fixed":false,"why":"u = t copies the reference, so both names refer to one object; changing it via u changes what t sees, and == is true because the addresses are equal.","source":"slide 16, verified","study":"05-copy-constructors.md — 4. `=` and `==` with objects; privacy leaks (slides 16–18, 25)","origin":"practice"},{"id":"w05-008","chapter":"w05","topic":"Aliasing & ==","type":"mcq","q":"ToyClass has a correct equals(ToyClass) comparing name and number.\nToyClass p = new ToyClass(\"A\", 1), q = new ToyClass(\"A\", 1);\nSystem.out.println((p == q) + \" \" + p.equals(q));\nWhat is printed?","options":["true true","true false","false true","false false"],"answer":2,"fixed":false,"why":"== compares memory addresses (two separate objects → false); equals compares the instance variables (equal → true).","source":"slide 16, verified","study":"05-copy-constructors.md — 4. `=` and `==` with objects; privacy leaks (slides 16–18, 25)","origin":"practice"},{"id":"w05-009","chapter":"w05","topic":"Aliasing & ==","type":"yn","q":"Person original = new Person(\"Emina\", 22);\nPerson copy = original;\nDoes the second line create a new Person object?","options":["Yes","No"],"answer":1,"fixed":false,"why":"It only copies the reference (aliasing): copy == original is true. Slide 24 calls this a 'shallow copy', but a shallow copy is still a new object — this is no copy at all.","source":"slides 16, 24, 33","study":"05-copy-constructors.md — 9. Errata (all verified with JDK 26.0.2)","origin":"practice"},{"id":"w05-010","chapter":"w05","topic":"Privacy leaks","type":"mcq","q":"Which statement matches the slide-18 definition of a privacy leak?","options":["A private method is called from outside the class","An object is printed with the default toString and shows its memory address","A class declares an instance variable public instead of private","A class exposes a direct reference to a mutable internal object, so outside code can change its private state without its knowledge"],"answer":3,"fixed":false,"why":"Slide 18: a privacy leak breaks encapsulation by handing out a live reference to a mutable private object; public fields are a different (more obvious) encapsulation failure.","source":"slide 18","study":"05-copy-constructors.md — 4. `=` and `==` with objects; privacy leaks (slides 16–18, 25)","origin":"practice"},{"id":"w05-011","chapter":"w05","topic":"Privacy leaks","type":"tf","q":"For a mutable class-type instance variable, declaring it private is enough to prevent privacy leaks.","options":["True","False"],"answer":1,"fixed":false,"why":"Slide 17: private is enough for primitives, but for class types a reference can still escape via arguments or return values.","source":"slide 17","study":"05-copy-constructors.md — 4. `=` and `==` with objects; privacy leaks (slides 16–18, 25)","origin":"practice"},{"id":"w05-012","chapter":"w05","topic":"Privacy leaks","type":"mcq","q":"Person has private String name and private Address address (Address has setters). Which getter can cause a privacy leak?","options":["public Address getAddress() { return address; }","public String getName() { return name; }","public Address getAddress() { return new Address(address); }","public int getAge() { return age; }"],"answer":0,"fixed":false,"why":"Returning the live Address lets the caller call its setters. String is immutable (slide 26) and the third getter returns a defensive copy.","source":"slides 26–28, 32","study":"05-copy-constructors.md — 6. Mutable vs immutable; the Moved Person / Address example (slides 26–32)","origin":"practice"},{"id":"w05-013","chapter":"w05","topic":"Privacy leaks","type":"mcq","q":"Slide 32: what is the correct body for getMovedToAddress() when movedTo is a mutable Address?","options":["return movedTo;","return new Address(movedTo);","return this;","return (Address) movedTo.clone;"],"answer":1,"fixed":false,"why":"A defensive copy via the copy constructor returns an independent object, so the caller cannot change movedTo.","source":"slide 32","study":"05-copy-constructors.md — 6. Mutable vs immutable; the Moved Person / Address example (slides 26–32)","origin":"practice"},{"id":"w05-014","chapter":"w05","topic":"Mutable vs immutable","type":"yn","q":"A field is declared  private final Address home;  and Address has a setCity method. Is the Address object stored in home immutable?","options":["Yes","No"],"answer":1,"fixed":false,"why":"final only stops the reference from being reassigned; home.setCity(...) still changes the object. Slide 29 wrongly says final makes it immutable.","source":"slide 29, verified with JDK 26","study":"05-copy-constructors.md — 9. Errata (all verified with JDK 26.0.2)","origin":"practice"},{"id":"w05-015","chapter":"w05","topic":"Mutable vs immutable","type":"mcq","q":"class Address { private String street; Address(String s) { street = s; }\n  void setStreet(String s) { street = s; } String getStreet() { return street; } }\n// in main:\nfinal Address f = new Address(\"X\");\nf.setStreet(\"Y\");\nSystem.out.println(f.getStreet());\nWhat happens?","options":["Compile error: f is final","Prints X","Prints Y","Runtime exception"],"answer":2,"fixed":false,"why":"final forbids f = new Address(...), not changing the object's contents through a setter.","source":"verified with JDK 26","study":"05-copy-constructors.md — 9. Errata (all verified with JDK 26.0.2)","origin":"practice"},{"id":"w05-016","chapter":"w05","topic":"Deep vs shallow copy","type":"mcq","q":"Which is the slide-33 definition of a deep copy?","options":["A copy made only of primitive fields","A copy made with the = operator","A copy that shares all its instance variables with the original","A copy that has no references in common with the original, except references to immutable objects"],"answer":3,"fixed":false,"why":"Slide 33: deep copy shares nothing except immutable objects (like String); anything else is a shallow copy.","source":"slide 33","study":"05-copy-constructors.md — 7. Deep copy vs shallow copy (slide 33)","origin":"practice"},{"id":"w05-017","chapter":"w05","topic":"Deep vs shallow copy","type":"mcq","q":"Inside Person's copy constructor:  this.address = other.address;  (Address is mutable). What kind of copy is the new Person?","options":["A shallow copy","No copy — an alias","A deep copy","An immutable copy"],"answer":0,"fixed":false,"why":"A new Person object is made, but its Address is shared with the original — the definition of a shallow copy.","source":"slide 33","study":"05-copy-constructors.md — 7. Deep copy vs shallow copy (slide 33)","origin":"practice"},{"id":"w05-018","chapter":"w05","topic":"Copy constructors","type":"tf","q":"Like C++, Java has a built-in, language-level copy constructor that is generated automatically.","options":["True","False"],"answer":1,"fixed":false,"why":"Slide 19: in Java it is only an idiom — you write a normal constructor taking the same type.","source":"slide 19","study":"05-copy-constructors.md — 5. Copy constructor (slides 19–24)","origin":"practice"},{"id":"w05-019","chapter":"w05","topic":"Copy constructors","type":"mcq","q":"Slide 5 shows ToyClass.equals as:\nreturn ((name.equals(otherObject.name)) && (number = otherObject.number));\nWhat happens when this is compiled?","options":["It compiles and compares the numbers","Compile error: && cannot combine boolean and int","It compiles but always returns true","Runtime NullPointerException"],"answer":1,"fixed":false,"why":"number = ... is an assignment of type int, so boolean && int is rejected ('bad operand types'). It must be ==.","source":"slide 5, verified with javac","study":"05-copy-constructors.md — 9. Errata (all verified with JDK 26.0.2)","origin":"practice"},{"id":"w05-020","chapter":"w05","topic":"Copy constructors","type":"mcq","q":"public Address(Address other) {\n  if (other == null) { System.out.println(\"other Object address is null\"); }\n  this.street = other.street;\n}\nWhat happens on  new Address(null)?","options":["Throws IllegalArgumentException","Prints the message and creates an Address with street null","Prints the message, then throws NullPointerException","Compile error"],"answer":2,"fixed":false,"why":"The check only prints; execution continues to other.street, which dereferences null. Slide 22's version throws IllegalArgumentException instead.","source":"slide 30, verified","study":"05-copy-constructors.md — 9. Errata (all verified with JDK 26.0.2)","origin":"practice"},{"id":"w05-021","chapter":"w05","topic":"Mutable vs immutable","type":"mcq","q":"Which of these classes is immutable?","options":["StringBuilder","int[] (an array)","An Address class with setCity","String"],"answer":3,"fixed":false,"why":"String has no methods that change its data (slide 27). StringBuilder, arrays and a class with setters can all be modified.","source":"slide 27","study":"05-copy-constructors.md — 6. Mutable vs immutable; the Moved Person / Address example (slides 26–32)","origin":"practice"},{"id":"w05-022","chapter":"w05","topic":"Deep vs shallow copy","type":"mcq","q":"Person's copy constructor does  this.address = new Address(other.address);\nPerson p = new Person(\"Emina\", new Address(\"Sarajevo\"));\nPerson q = new Person(p);\nq.getAddressDirect().setCity(\"Mostar\");   // returns the field itself\nSystem.out.println(p.getAddressDirect().getCity());\nWhat is printed?","options":["Sarajevo","Mostar","null","Compile error"],"answer":0,"fixed":false,"why":"The copy constructor made a new Address, so q's address is independent; the original keeps Sarajevo.","source":"slide 29, verified (exercise w05 E3)","study":"05-copy-constructors.md — 7. Deep copy vs shallow copy (slide 33)","origin":"practice"},{"id":"w05-023","chapter":"w05","topic":"Deep vs shallow copy","type":"mcq","q":"Same as before, but the copy constructor does  this.address = other.address;\nAfter q.getAddressDirect().setCity(\"Mostar\"), what does  p.getAddressDirect().getCity()  return?","options":["Sarajevo","Mostar","null","Compile error"],"answer":1,"fixed":false,"why":"A shallow copy shares the Address object, so the change made through q is seen through p.","source":"slide 33, verified","study":"05-copy-constructors.md — 7. Deep copy vs shallow copy (slide 33)","origin":"practice"},{"id":"w05-024","chapter":"w05","topic":"Class parameters","type":"mcq","q":"static void f(int[] a) { a[0] = 9; }\nstatic void g(int[] a) { a = new int[]{7, 7}; a[1] = 5; }\n// in main:\nint[] x = {1, 2};\nf(x); g(x);\nSystem.out.println(x[0] + \" \" + x[1]);\nWhat is printed?","options":["1 2","9 5","9 2","7 5"],"answer":2,"fixed":false,"why":"f changes the shared array (9). g makes its parameter point to a new array, so a[1] = 5 changes only that new array.","source":"slides 2–3, verified","study":"05-copy-constructors.md — 1. Java is always call-by-value (slides 2–3, 9)","origin":"practice"},{"id":"w05-025","chapter":"w05","topic":"Aliasing & ==","type":"yn","q":"Can a static method inside ToyClass assign to the private fields of a ToyClass object passed to it as a parameter (as changer does)?","options":["Yes","No"],"answer":0,"fixed":false,"why":"private means private to the class, not to one object, so code inside ToyClass may access other.name — this is also how copy constructors work.","source":"slide 5, verified","study":"05-copy-constructors.md — 2. Display 5.14 — `ToyClass.changer` (slides 4–8, 10)","origin":"practice"},{"id":"w05-026","chapter":"w05","topic":"Privacy leaks","type":"mcq","q":"Through which two routes can a live reference to a private mutable field escape (slide 18)?","options":["It is used in a loop, or in a constructor","It is declared final, or it is declared static","It is printed, or it is compared with ==","It is passed in as an argument and stored, or it is returned from a method"],"answer":3,"fixed":false,"why":"Slide 18: sending the live reference as an argument to, or returning it from, a method. Copy constructors on the way in and out stop both.","source":"slide 18","study":"05-copy-constructors.md — 4. `=` and `==` with objects; privacy leaks (slides 16–18, 25)","origin":"practice"},{"id":"w05-027","chapter":"w05","topic":"Copy constructors","type":"tf","q":"A copy constructor is a constructor with a single parameter whose type is the same class.","options":["True","False"],"answer":0,"fixed":false,"why":"Slide 19: one argument of the same type as the class, e.g. Person(Person other).","source":"slide 19","study":"05-copy-constructors.md — 5. Copy constructor (slides 19–24)","origin":"practice"},{"id":"w05-028","chapter":"w05","topic":"Mutable vs immutable","type":"mcq","q":"String s = \"a\";\nString t = s;\nt = t + \"b\";\nSystem.out.println(s);\nWhat is printed?","options":["a","b","ab","null"],"answer":0,"fixed":false,"why":"String is immutable: t + \"b\" builds a new String and t now points to it; s still names the original \"a\". That is why returning a String field is safe.","source":"slides 26–27, verified","study":"05-copy-constructors.md — 6. Mutable vs immutable; the Moved Person / Address example (slides 26–32)","origin":"practice"},{"id":"w05-029","chapter":"w05","topic":"Class parameters","type":"mcq","q":"In Dr. Oladejo's 'Multiple Developer' story (slide 11), what went wrong?","options":["Developer 1 forgot to write a constructor","Developer 2's changer() — not a setter — changed the field values of Developer 1's object through a class-type parameter","Developer 2 made the fields public","Both developers created objects with the same name"],"answer":1,"fixed":false,"why":"changer received a reference to anObject and changed its fields, so the calling program's object changed behind Developer 1's back.","source":"slide 11","study":"05-copy-constructors.md — 2. Display 5.14 — `ToyClass.changer` (slides 4–8, 10)","origin":"practice"},{"id":"w05-030","chapter":"w05","topic":"Deep vs shallow copy","type":"yn","q":"When writing a deep copy, may the copy share the original's String fields?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Slide 33's exception: references to immutable objects (such as String) may be shared.","source":"slide 33","study":"05-copy-constructors.md — 7. Deep copy vs shallow copy (slide 33)","origin":"practice"},{"id":"w06-001","chapter":"w06","topic":"Types & is-a","type":"mcq","q":"An ancestor cannot be used wherever one of its descendants can be used. Why?","options":["Because the derived class may have specifications that are not in the parent class","Because the ancestor's constructors are private","Because Java only allows one level of inheritance","Because the ancestor does not inherit from Object"],"answer":0,"fixed":false,"why":"Slide 13's answer: the child may add members (e.g. openClose) the parent lacks, so a parent object cannot stand in for a child.","source":"slide 13","study":"06-inheritance.md — 7. An object has more than one type; is-a vs has-a (slides 13, 26–27, 37–45)","origin":"professor"},{"id":"w06-002","chapter":"w06","topic":"Overriding vs overloading","type":"mcq","q":"What is a method signature?","options":["The method's name, parameter list and return type","The combination of the method's name and its parameter list","The method's access modifier and name","The method's name and return type"],"answer":1,"fixed":false,"why":"Slide 14: name + parameter list; return type and access modifiers are not included — that is why changing only the return type is not an overload.","source":"slide 14","study":"06-inheritance.md — 4. Overriding (slides 14–19)","origin":"professor"},{"id":"w06-003","chapter":"w06","topic":"super & this constructors","type":"mcq","q":"Why can an instance variable of the derived class not be used as an argument to super(...)?","options":["Because instance variables are always private","Because super only accepts literal values","Because of the order of initialization: the superclass constructor must run before the subclass's own instance variables are initialized or ready","Because the base class cannot see derived-class names at run time"],"answer":2,"fixed":false,"why":"Slide 22's answer. javac reports 'reference to v may only appear after an explicit constructor invocation'.","source":"slide 22, verified with JDK 26","study":"06-inheritance.md — 6. Constructors: `super(...)` and `this(...)` (slides 21–25, 29–30)","origin":"professor"},{"id":"w06-004","chapter":"w06","topic":"Object, equals & getClass","type":"mcq","q":"instanceof returns true not only for the class tested but also for its descendants. Why?","options":["Because every class extends Object directly","Because instanceof ignores the class name","Because getClass() is final","Because the descendant is a type of the ancestor"],"answer":3,"fixed":false,"why":"Slide 65's answer: a descendant object has the type of every ancestor (is-a), so x instanceof Employee is true for an HourlyEmployee.","source":"slide 65","study":"06-inheritance.md — 10. Class `Object`; `equals`, `toString`, `getClass` (slides 59–69)","origin":"professor"},{"id":"w06-005","chapter":"w06","topic":"Inheritance basics","type":"mcq","q":"Which term is NOT a synonym for 'base class'?","options":["Descendant class","Parent class","Ancestor class","Superclass"],"answer":0,"fixed":false,"why":"Base = super = parent = ancestor; descendant is a synonym for the derived class.","source":"slide 5","study":"06-inheritance.md — 1. Vocabulary (slides 3–5, 28)","origin":"practice"},{"id":"w06-006","chapter":"w06","topic":"Inheritance basics","type":"tf","q":"A superclass is more general and inclusive, while a subclass is more specialized and more complex.","options":["True","False"],"answer":0,"fixed":false,"why":"Slide 28: the terms are often mistakenly reversed — the subclass adds members, so fewer objects satisfy it.","source":"slide 28","study":"06-inheritance.md — 1. Vocabulary (slides 3–5, 28)","origin":"practice"},{"id":"w06-007","chapter":"w06","topic":"Types & is-a","type":"mcq","q":"class Device { public String status() { return \"Generic device status.\"; } }\nclass DoorDevice extends Device {\n  private boolean isOpen = false;\n  @Override public String status() { return isOpen ? \"Door is open.\" : \"Door is closed.\"; }\n  public void openClose() { isOpen = !isOpen; System.out.println(\"Door toggled. \" + status()); }\n}\n// in main:\nDevice d = new DoorDevice();\nSystem.out.println(d.status());\nWhat is printed?","options":["Generic device status.","Door is closed.","Door is open.","Compile error"],"answer":1,"fixed":false,"why":"The object is a DoorDevice, so its overriding status() runs even through a Device variable; isOpen starts false.","source":"slides 8–9, verified","study":"06-inheritance.md — 2. The Device example (slides 6–11, instructor's own)","origin":"practice"},{"id":"w06-008","chapter":"w06","topic":"Overriding vs overloading","type":"mcq","q":"class Device { public String status() { return \"Generic device status.\"; } }\nclass DoorDevice extends Device {\n  private boolean isOpen = false;\n  @Override public String status() { return isOpen ? \"Door is open.\" : \"Door is closed.\"; }\n  public void openClose() { isOpen = !isOpen; System.out.println(\"Door toggled. \" + status()); }\n}\n// in main:\nDoorDevice door = new DoorDevice();\ndoor.openClose();\ndoor.openClose();\nWhat is the second line printed?","options":["Door toggled. Door is open.","Door toggled. Generic device status.","Door toggled. Door is closed.","Door is closed."],"answer":2,"fixed":false,"why":"First call: closed → open. Second call: open → closed, printing 'Door toggled. Door is closed.'","source":"slide 9, verified","study":"06-inheritance.md — 2. The Device example (slides 6–11, instructor's own)","origin":"practice"},{"id":"w06-009","chapter":"w06","topic":"Types & is-a","type":"yn","q":"class Device { public String status() { return \"Generic device status.\"; } }\nclass DoorDevice extends Device {\n  private boolean isOpen = false;\n  @Override public String status() { return isOpen ? \"Door is open.\" : \"Door is closed.\"; }\n  public void openClose() { isOpen = !isOpen; System.out.println(\"Door toggled. \" + status()); }\n}\n// in main:\nDevice d = new DoorDevice();\nd.openClose();\nDoes this compile?","options":["Yes","No"],"answer":1,"fixed":false,"why":"The compiler checks the variable's type, Device, which has no openClose(). An ancestor type cannot use the descendant's extra methods.","source":"slides 13, 27, verified","study":"06-inheritance.md — 7. An object has more than one type; is-a vs has-a (slides 13, 26–27, 37–45)","origin":"practice"},{"id":"w06-010","chapter":"w06","topic":"super & this constructors","type":"mcq","q":"class ThermostatDevice extends Device {\n  private int temperature;\n  public ThermostatDevice(String m, String s) { this(m, s, 20); }\n  public ThermostatDevice(String m, String s, int temp) { super(m, s); temperature = temp; }\n  public String status() { return \"Current temperature is \" + temperature + \" C.\"; }\n}\nSystem.out.println(new ThermostatDevice(\"T\", \"1\").status());\nWhat is printed?","options":["Current temperature is 0 C.","Generic device status.","Compile error: this and super in one class","Current temperature is 20 C."],"answer":3,"fixed":false,"why":"The 2-arg constructor passes the default 20 to the explicit-value constructor via this(...), which calls super first.","source":"slides 10, 25, verified","study":"06-inheritance.md — 6. Constructors: `super(...)` and `this(...)` (slides 21–25, 29–30)","origin":"practice"},{"id":"w06-011","chapter":"w06","topic":"super & this constructors","type":"mcq","q":"class A { A() { System.out.print(\"A \"); } }\nclass B extends A { B() { this(1); System.out.print(\"B \"); }\n                  B(int x) { System.out.print(\"Bint \"); } }\nclass C extends B { C() { System.out.print(\"C \"); } }\n// in main:\nnew C();\nWhat is printed?","options":["A Bint B C","C B Bint A","A B Bint C","Bint B A C"],"answer":0,"fixed":false,"why":"C() implicitly calls B(); B() calls this(1); B(int) implicitly calls A(). Bodies finish parent-first: A, Bint, B, C.","source":"slides 23–24, verified","study":"06-inheritance.md — 6. Constructors: `super(...)` and `this(...)` (slides 21–25, 29–30)","origin":"practice"},{"id":"w06-012","chapter":"w06","topic":"super & this constructors","type":"mcq","q":"class Base { Base(int x) { } }\nclass Sub extends Base { Sub() { } }\nWhat happens?","options":["Compiles; Base gets x = 0","Compile error: Sub() implicitly calls super(), but Base has no no-argument constructor","Runtime exception when new Sub() runs","Compiles because constructors are inherited"],"answer":1,"fixed":false,"why":"Slide 23: without an explicit super(...), Java inserts super(); Base only has Base(int), so it does not compile.","source":"slide 23, verified with javac","study":"06-inheritance.md — 6. Constructors: `super(...)` and `this(...)` (slides 21–25, 29–30)","origin":"practice"},{"id":"w06-013","chapter":"w06","topic":"Overriding vs overloading","type":"mcq","q":"class P { public void go() { } }\nclass Q extends P { private void go() { } }\nWhat happens?","options":["Compiles: Q.go overloads P.go","Compiles: private hides the method","Compile error: attempting to assign weaker access privileges","Runtime IllegalAccessError"],"answer":2,"fixed":false,"why":"Slides 17–18: an overriding method may be more permissive, never more restrictive.","source":"slide 18, verified with javac","study":"06-inheritance.md — 4. Overriding (slides 14–19)","origin":"practice"},{"id":"w06-014","chapter":"w06","topic":"Overriding vs overloading","type":"yn","q":"Base class: public Employee getSomeone(int key)\nDerived class: public HourlyEmployee getSomeone(int key)   (HourlyEmployee extends Employee)\nIs this a legal override?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Covariant return type (Java 5.0+): a class return type may be replaced by a descendant class.","source":"slides 15–16","study":"06-inheritance.md — 4. Overriding (slides 14–19)","origin":"practice"},{"id":"w06-015","chapter":"w06","topic":"Overriding vs overloading","type":"yn","q":"class B { int f() { return 1; } }\nclass D extends B { long f() { return 2; } }\nIs this a legal override?","options":["Yes","No"],"answer":1,"fixed":false,"why":"Covariance applies only to class types. For a primitive the return type must stay the same: 'return type long is not compatible with int'.","source":"slide 15, verified with javac","study":"06-inheritance.md — 4. Overriding (slides 14–19)","origin":"practice"},{"id":"w06-016","chapter":"w06","topic":"Overriding vs overloading","type":"mcq","q":"Inside class Employee:  public boolean equals(Employee other) { ... }\nWhat does this do to Object's equals(Object)?","options":["Overrides it","Causes a compile error","Hides it so it can no longer be called","Overloads it — equals(Object) is still inherited"],"answer":3,"fixed":false,"why":"Slide 62: a different parameter type means a different signature, so it is an overload; the inherited equals(Object) remains.","source":"slide 62","study":"06-inheritance.md — 10. Class `Object`; `equals`, `toString`, `getClass` (slides 59–69)","origin":"practice"},{"id":"w06-017","chapter":"w06","topic":"Object, equals & getClass","type":"mcq","q":"class Emp { String name; Emp(String n) { name = n; }\n  public boolean equals(Emp o) { return o != null && name.equals(o.name); } }\n// in main:\nList<Emp> list = new ArrayList<>();\nlist.add(new Emp(\"Joe\"));\nSystem.out.println(list.contains(new Emp(\"Joe\")));\nWhat is printed?","options":["false","true","Compile error","ClassCastException"],"answer":0,"fixed":false,"why":"ArrayList.contains calls equals(Object), which is still Object's identity check because equals(Emp) only overloads it.","source":"slides 61–62, verified","study":"06-inheritance.md — 10. Class `Object`; `equals`, `toString`, `getClass` (slides 59–69)","origin":"practice"},{"id":"w06-018","chapter":"w06","topic":"Object, equals & getClass","type":"tf","q":"The getClass() method can be overridden to make equals more flexible.","options":["True","False"],"answer":1,"fixed":false,"why":"Slide 69: getClass() is marked final in Object, so it cannot be overridden.","source":"slide 69","study":"06-inheritance.md — 10. Class `Object`; `equals`, `toString`, `getClass` (slides 59–69)","origin":"practice"},{"id":"w06-019","chapter":"w06","topic":"Inheritance basics","type":"mcq","q":"What does the modifier final mean when placed before a class definition?","options":["Its methods cannot be called","The class cannot be used as a base class to derive other classes","Its objects cannot be changed","It must have a no-argument constructor"],"answer":1,"fixed":false,"why":"Slide 20: a final class cannot be extended; a final method cannot be overridden. Neither makes objects immutable.","source":"slide 20","study":"06-inheritance.md — 5. `final` (slide 20)","origin":"practice"},{"id":"w06-020","chapter":"w06","topic":"Overriding vs overloading","type":"mcq","q":"Person ← Employee ← HourlyEmployee. Inside HourlyEmployee, which call invokes Person's toString()?","options":["super.super.toString()","Person.super.toString()","super.toString()","None of these — you cannot skip a generation with super"],"answer":3,"fixed":true,"why":"Slide 58: super reaches only the direct parent; super.super is illegal (compile error).","source":"slide 58, verified with javac","study":"06-inheritance.md — 9. `super.method()` (slides 57–58)","origin":"practice"},{"id":"w06-021","chapter":"w06","topic":"Overriding vs overloading","type":"mcq","q":"class Employee { private String name; Employee(String n) { name = n; }\n  public String toString() { return name; } }\nclass HourlyEmployee extends Employee { private double wageRate;\n  HourlyEmployee(String n, double w) { super(n); wageRate = w; }\n  public String toString() { return super.toString() + \"$\" + wageRate; } }\n// in main:\nSystem.out.println(new HourlyEmployee(\"Ann\", 8.5));\nWhat is printed?","options":["$8.5","HourlyEmployee@1b6d3586","Ann$8.5","Compile error: name is private"],"answer":2,"fixed":false,"why":"super.toString() runs Employee's version (\"Ann\"), then \"$8.5\" is appended. name is never used by name in the subclass, so private is fine.","source":"slide 57, verified","study":"06-inheritance.md — 9. `super.method()` (slides 57–58)","origin":"practice"},{"id":"w06-022","chapter":"w06","topic":"Access modifiers","type":"mcq","q":"Display 7.9: A (package somePackage) has public v1, protected v2, package-access v3, private v4. Class D extends A but is in a DIFFERENT package. Which can D access by name?","options":["v1 only","v1, v2, v3 and v4","v1, v2 and v3","v1 and v2"],"answer":3,"fixed":false,"why":"A derived class in another package gets public and protected members; package access stops at the package border; private is never visible.","source":"slide 52","study":"06-inheritance.md — 8. Access modifiers (slides 49–55)","origin":"practice"},{"id":"w06-023","chapter":"w06","topic":"Access modifiers","type":"mcq","q":"Which order is correct from MOST restrictive to LEAST restrictive?","options":["private, protected, package, public","private, package, protected, public","package, private, protected, public","private, package, public, protected"],"answer":1,"fixed":true,"why":"Slide 51: package access is more restricted than protected (protected = package + subclasses).","source":"slides 49–51","study":"06-inheritance.md — 8. Access modifiers (slides 49–55)","origin":"practice"},{"id":"w06-024","chapter":"w06","topic":"Access modifiers","type":"yn","q":"package pa;  public class A { protected int n; }\npackage pb;  public class B extends pa.A {\n  int get() { pa.A a = new pa.A(); return a.n; }\n}\nDoes B compile?","options":["Yes","No"],"answer":1,"fixed":false,"why":"Slides 54–55: in a different package, B can use n as its own inherited member, but not through an object created from class A ('n has protected access in A').","source":"slides 54–55, verified with javac","study":"06-inheritance.md — 8. Access modifiers (slides 49–55)","origin":"practice"},{"id":"w06-025","chapter":"w06","topic":"Access modifiers","type":"tf","q":"A derived class can access a private instance variable of its base class by name.","options":["True","False"],"answer":1,"fixed":false,"why":"Slide 46: it is inherited but not accessible by name; use the base class's public accessor/mutator methods.","source":"slide 46","study":"06-inheritance.md — 3. What a derived class inherits (slides 12, 41–42, 46–48, 56)","origin":"practice"},{"id":"w06-026","chapter":"w06","topic":"super & this constructors","type":"tf","q":"Static variables in a base class are inherited by its derived classes.","options":["True","False"],"answer":0,"fixed":false,"why":"Slide 56; public/private/protected/package mean the same thing for static variables.","source":"slide 56","study":"06-inheritance.md — 3. What a derived class inherits (slides 12, 41–42, 46–48, 56)","origin":"practice"},{"id":"w06-027","chapter":"w06","topic":"Object, equals & getClass","type":"mcq","q":"Employee.equals and HourlyEmployee.equals both use instanceof (Employee and HourlyEmployee respectively) and compare the name.\nEmployee e = new Employee(\"Joe\");\nHourlyEmployee h = new HourlyEmployee(\"Joe\", 8.5);\nSystem.out.println(e.equals(h) + \" \" + h.equals(e));\nWhat is printed?","options":["true false","false false","true true","false true"],"answer":0,"fixed":false,"why":"h instanceof Employee is true, but e instanceof HourlyEmployee is false — equals becomes asymmetric (slides 66–67). getClass() avoids this.","source":"slides 65–67, verified","study":"06-inheritance.md — 10. Class `Object`; `equals`, `toString`, `getClass` (slides 59–69)","origin":"practice"},{"id":"w06-028","chapter":"w06","topic":"Object, equals & getClass","type":"mcq","q":"class Employee { }  class HourlyEmployee extends Employee { }\nObject o = new HourlyEmployee();\nSystem.out.println((o instanceof Employee) + \" \" + (o.getClass() == Employee.class));\nWhat is printed?","options":["true true","true false","false true","false false"],"answer":1,"fixed":false,"why":"instanceof is true for descendants; getClass() returns exactly the class used with new (HourlyEmployee), so the comparison is false.","source":"slides 68–69, verified","study":"06-inheritance.md — 10. Class `Object`; `equals`, `toString`, `getClass` (slides 59–69)","origin":"practice"},{"id":"w06-029","chapter":"w06","topic":"Types & is-a","type":"mcq","q":"Employee contains an instance variable  private Address address;  Which relationship is that?","options":["\"is a\" — inheritance","\"uses a\" — overloading","\"has a\" — composition","\"is a\" — polymorphism"],"answer":2,"fixed":false,"why":"Slide 44: an instance variable of a class type is composition (has-a). is-a comes from extends.","source":"slides 43–45","study":"06-inheritance.md — 7. An object has more than one type; is-a vs has-a (slides 13, 26–27, 37–45)","origin":"practice"},{"id":"w06-030","chapter":"w06","topic":"Overriding vs overloading","type":"mcq","q":"class Base { private void doSomething() { } }\nclass Derived extends Base { @Override public void doSomething() { } }\nWhat happens?","options":["Compiles: access widened from private to public","Runtime error","Compiles, and Base.doSomething() is now public","Compile error: the method does not override anything, because a private method is not inherited"],"answer":3,"fixed":false,"why":"Slides 17–18 say private → public is allowed, but that is a new method, not an override; @Override exposes it with 'does not override or implement a method from a supertype'.","source":"slides 17–18, 48, verified with javac","study":"06-inheritance.md — 4. Overriding (slides 14–19)","origin":"practice"},{"id":"w06-031","chapter":"w06","topic":"Object, equals & getClass","type":"mcq","q":"Device has no toString(). What does  System.out.println(new Device(\"M\", \"1\"));  print?","options":["Something like Device@4961f6af (class name @ hash code)","M 1","Device{model=M, serialNumber=1}","Compile error: Device has no toString"],"answer":0,"fixed":false,"why":"toString is inherited from Object (slide 61), which prints the class name, '@' and a hex hash code — which is why it should be overridden.","source":"slides 59–61, verified","study":"06-inheritance.md — 10. Class `Object`; `equals`, `toString`, `getClass` (slides 59–69)","origin":"practice"},{"id":"w06-032","chapter":"w06","topic":"Object, equals & getClass","type":"mcq","q":"EnhancedStringTokenizer (Display 7.7) overrides nextToken() and nextToken(String), and both store the token. On JDK 26:\nEnhancedStringTokenizer t = new EnhancedStringTokenizer(\"a b c d\");\nt.nextToken(\" \");\nSystem.out.println(Arrays.toString(t.tokensSoFar()));\nWhat is printed?","options":["[a]","[a, a]","[]","[a, b]"],"answer":1,"fixed":false,"why":"StringTokenizer.nextToken(String) internally calls nextToken(), which by dynamic binding is the overriding version that stores the token; then nextToken(String) stores it again.","source":"slides 33–36, verified with JDK 26","study":"06-inheritance.md — 11. The EnhancedStringTokenizer (slides 31–36, Display 7.7)","origin":"practice"},{"id":"w06-033","chapter":"w06","topic":"Inheritance basics","type":"mcq","q":"What did Dr. Oladejo announce for this week's Graded Lab One (slide 2)?","options":["10 points, all practical","5 points, all theory, on UML","5 points: 4 practical + 1 theory, on Inheritance I","4 points: 3 practical + 1 theory, on exceptions"],"answer":2,"fixed":false,"why":"Slide 2: Graded Lab One, 5 points (4 practical, 1 theory), lab Inheritance I; Inheritance II comes after the midterm.","source":"slide 2","study":"06-inheritance.md — Instructor items box at top","origin":"practice"},{"id":"w06-034","chapter":"w06","topic":"Inheritance basics","type":"tf","q":"A derived class inherits the constructors of its base class.","options":["True","False"],"answer":1,"fixed":false,"why":"Constructors are not inherited; the derived class calls them with super(...) (slides 21–23).","source":"slides 21–23","study":"06-inheritance.md — 3. What a derived class inherits (slides 12, 41–42, 46–48, 56)","origin":"practice"},{"id":"w07-001","chapter":"w07","topic":"Scanner & InputMismatchException","type":"mcq","q":"In the demo WholeNumExceptionDemo.java (slide 13), where does the exception come from in the code?","options":["nextInt()","System.out.println()","the while (!done) condition","new Scanner(System.in)"],"answer":0,"fixed":false,"why":"The professor's answer on slide 13: nextInt() throws InputMismatchException when the input is not a whole number. Creating the Scanner or printing never throws here.","source":"slide 13 (red in-class question) · slide 14 Display 9.1","study":"07-exception-handling.md — 3. Library exceptions and Scanner (slides 9–14)","origin":"professor"},{"id":"w07-002","chapter":"w07","topic":"Scanner & InputMismatchException","type":"mcq","q":"In Display 9.1 (slide 14) the user types forty two. Which exception does nextInt() throw?","options":["NumberFormatException","InputMismatchException","IOException","IllegalStateException"],"answer":1,"fixed":false,"why":"Scanner.nextInt() throws InputMismatchException (java.util). NumberFormatException is what Integer.parseInt throws, a common mix-up.","source":"slides 9–11, 14","study":"07-exception-handling.md — 3. Library exceptions and Scanner (slides 9–14)","origin":"practice","twin":"w07-001"},{"id":"w07-003","chapter":"w07","topic":"Scanner & InputMismatchException","type":"yn","q":"In the exception-controlled loop of Display 9.1, is the statement done = true; executed when nextInt() throws?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. The throw ends the try block at nextInt(), so done = true is skipped and the loop repeats. That is the whole trick of the pattern.","source":"slide 14 annotation","study":"07-exception-handling.md — 3. Library exceptions and Scanner (slides 9–14)","origin":"practice","twin":"w07-001"},{"id":"w07-004","chapter":"w07","topic":"Scanner & InputMismatchException","type":"tf","q":"InputMismatchException is an unchecked exception, so it does not have to be caught or declared.","options":["True","False"],"answer":0,"fixed":false,"why":"True: it descends from RuntimeException (slide 11). Catching it is allowed and often useful, but not required.","source":"slide 11","study":"07-exception-handling.md — 3. Library exceptions and Scanner (slides 9–14)","origin":"practice"},{"id":"w07-005","chapter":"w07","topic":"Scanner & InputMismatchException","type":"mcq","q":"What does this print?\nScanner in = new Scanner(\"x 7\");\nint tries = 0, n = 0;\nboolean done = false;\nwhile (!done) {\n    try { tries++; n = in.nextInt(); done = true; }\n    catch (InputMismatchException e) { in.next(); }\n}\nSystem.out.println(n + \" \" + tries);","options":["7 1","0 2","7 2","Infinite loop"],"answer":2,"fixed":false,"why":"First try: 'x' is not an int → exception, in.next() discards it. Second try reads 7. So n = 7 after 2 tries.","source":"slide 12–14 pattern; verified on JDK 26","study":"07-exception-handling.md — 3. Library exceptions and Scanner (slides 9–14)","origin":"practice"},{"id":"w07-006","chapter":"w07","topic":"Scanner & InputMismatchException","type":"mcq","q":"In Display 9.1, keyboard.nextLine() is removed from the catch block and the user types abc. What happens?","options":["The program crashes with InputMismatchException","number becomes 0 and the loop ends","It does not compile","The loop repeats forever"],"answer":3,"fixed":false,"why":"The bad token is never consumed, so every nextInt() call fails on the same 'abc' and done never becomes true. (A test with a 1000-iteration cap ran all 1000.)","source":"slide 14; verified with a capped loop","study":"07-exception-handling.md — 3. Library exceptions and Scanner (slides 9–14)","origin":"practice"},{"id":"w07-007","chapter":"w07","topic":"try-catch-finally flow","type":"mcq","q":"What does this print (one value per line)?\ntry {\n    System.out.println(\"A\");\n    throw new Exception(\"B\");\n} catch (Exception e) {\n    System.out.println(e.getMessage());\n} finally {\n    System.out.println(\"C\");\n}\nSystem.out.println(\"D\");","options":["A C D","A B C D","A B D","B C D"],"answer":1,"fixed":false,"why":"A prints, the throw jumps to the catch which prints the message B, finally prints C, then execution continues with D.","source":"slides 6–7, 40–41; verified","study":"07-exception-handling.md — 10. finally (slides 40–41)","origin":"practice"},{"id":"w07-008","chapter":"w07","topic":"try-catch-finally flow","type":"mcq","q":"Given this method, what does System.out.println(t(1)); print?\nstatic String t(int k) {\n    String s = \"\";\n    try {\n        s += \"A\";\n        if (k == 1) throw new IllegalStateException();\n        s += \"B\";\n    } catch (IllegalStateException e) { s += \"C\"; }\n      finally { s += \"F\"; }\n    return s + \"E\";\n}","options":["ACE","ABCFE","AFE","ACFE"],"answer":3,"fixed":false,"why":"A is added, the throw skips B, the catch adds C, finally adds F, then E is appended after the try statement.","source":"slides 40–41; verified","study":"07-exception-handling.md — 10. finally (slides 40–41)","origin":"practice"},{"id":"w07-009","chapter":"w07","topic":"try-catch-finally flow","type":"mcq","q":"What does this print?\nint count = 0;\nfor (int i = 0; i < 3; i++) {\n    try {\n        if (i == 1) throw new RuntimeException();\n        count += 10;\n    } catch (RuntimeException e) {\n        count += 1;\n        continue;\n    } finally {\n        count += 100;\n    }\n}\nSystem.out.println(count);","options":["221","321","311","320"],"answer":1,"fixed":false,"why":"i=0: 10+100; i=1: 1+100 (finally runs even on continue); i=2: 10+100. Total 321. 221 forgets that finally runs before continue.","source":"slides 40–41; verified","study":"07-exception-handling.md — 10. finally (slides 40–41)","origin":"practice"},{"id":"w07-010","chapter":"w07","topic":"try-catch-finally flow","type":"mcq","q":"What does this print (one value per line)?\ntry {\n    try { throw new IllegalArgumentException(\"in\"); }\n    catch (NullPointerException e) { System.out.println(\"NPE\"); }\n    finally { System.out.println(\"F1\"); }\n    System.out.println(\"X\");\n} catch (IllegalArgumentException e) {\n    System.out.println(\"outer \" + e.getMessage());\n}","options":["F1 outer in","NPE F1 X","F1 X outer in","outer in F1"],"answer":0,"fixed":false,"why":"The inner catch does not match, so the inner finally runs (F1) and the exception leaves the inner try statement, skipping X. The outer catch prints 'outer in'.","source":"slide 41 case 3; verified","study":"07-exception-handling.md — 10. finally (slides 40–41)","origin":"practice"},{"id":"w07-011","chapter":"w07","topic":"try-catch-finally flow","type":"mcq","q":"What does System.out.println(f()); print (one value per line)?\nstatic int f() {\n    try { return 1; }\n    finally { System.out.println(\"fin\"); }\n}","options":["1","1 fin","fin 1","fin"],"answer":2,"fixed":false,"why":"finally runs before the method really returns, so 'fin' is printed first, then main prints the returned 1.","source":"beyond slides (finally semantics); verified","study":"07-exception-handling.md — 10. finally (slides 40–41)","origin":"practice"},{"id":"w07-012","chapter":"w07","topic":"try-catch-finally flow","type":"mcq","q":"What does this print?\ntry {\n    System.out.println(\"try\");\n    System.exit(0);\n} finally {\n    System.out.println(\"finally\");\n}","options":["try finally","finally try","finally","try"],"answer":3,"fixed":false,"why":"System.exit(0) stops the JVM at once, so the finally block never runs. This is the one common case where finally is skipped.","source":"slide 18 uses System.exit; verified","study":"07-exception-handling.md — 10. finally (slides 40–41)","origin":"practice"},{"id":"w07-013","chapter":"w07","topic":"try-catch-finally flow","type":"tf","q":"If an exception is thrown in a try block and no catch block in the method matches it, the finally block is skipped and the exception goes to the caller.","options":["True","False"],"answer":1,"fixed":false,"why":"False. Slide 41 case 3: the finally block is executed first, then the method ends and the exception is thrown to the enclosing method.","source":"slide 41","study":"07-exception-handling.md — 10. finally (slides 40–41)","origin":"practice"},{"id":"w07-014","chapter":"w07","topic":"try-catch-finally flow","type":"mcq","q":"What does this code in main print (one value per line)?\nstatic void inner() {\n    try { throw new RuntimeException(\"deep\"); }\n    finally { System.out.println(\"inner finally\"); }\n}\ntry {\n    inner();\n    System.out.println(\"after\");\n} catch (RuntimeException e) {\n    System.out.println(\"caught \" + e.getMessage());\n}","options":["caught deep","inner finally after","inner finally caught deep","after caught deep"],"answer":2,"fixed":false,"why":"inner() has no catch, so its finally prints first, then the exception propagates to main. 'after' is skipped because the call threw.","source":"slides 33, 41; verified","study":"07-exception-handling.md — 10. finally (slides 40–41)","origin":"practice"},{"id":"w07-015","chapter":"w07","topic":"Custom exception classes","type":"mcq","q":"Using slide 22's class, what does this print?\nclass DivisionByZeroException extends Exception {\n    public DivisionByZeroException() { super(\"Division by Zero!\"); }\n    public DivisionByZeroException(String message) { super(message); }\n}\ntry {\n    int d = 0;\n    if (d == 0) throw new DivisionByZeroException();\n    System.out.println(\"ok\");\n} catch (DivisionByZeroException e) {\n    System.out.println(e.getMessage());\n}","options":["null","Division by Zero!","DivisionByZeroException","/ by zero"],"answer":1,"fixed":false,"why":"The no-arg constructor passes the default string to super, so getMessage() returns 'Division by Zero!'. '/ by zero' is the message of the built-in ArithmeticException.","source":"slides 22, 24; verified","study":"07-exception-handling.md — 5. Defining your own exception class (slides 20–28)","origin":"practice"},{"id":"w07-016","chapter":"w07","topic":"Custom exception classes","type":"mcq","q":"What does this print?\nclass MyEx extends Exception {\n    public MyEx() { super(); }\n    public MyEx(String m) { super(m); }\n}\nSystem.out.println(new MyEx().getMessage() + \" \" + new MyEx(\"hi\").getMessage());","options":["hi hi","MyEx hi","null hi"," hi"],"answer":2,"fixed":false,"why":"super() with no argument leaves the message null, and string concatenation prints null. That is why slide 28 wants the no-arg constructor to pass a default string.","source":"slide 28; verified","study":"07-exception-handling.md — 5. Defining your own exception class (slides 20–28)","origin":"practice"},{"id":"w07-017","chapter":"w07","topic":"Custom exception classes","type":"mcq","q":"According to slide 28, how must the String constructor of a programmer-defined exception class begin?","options":["this.message = message;","super(message);","super();","getMessage(message);"],"answer":1,"fixed":false,"why":"The body begins with a call to super using the parameter, so the inherited getMessage() returns it. There is no message field you are meant to set yourself.","source":"slide 28","study":"07-exception-handling.md — 5. Defining your own exception class (slides 20–28)","origin":"practice"},{"id":"w07-018","chapter":"w07","topic":"Custom exception classes","type":"yn","q":"Can a programmer-defined exception class be derived from another programmer-defined exception class?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. Slide 21: it can be derived from any exception class in the standard libraries or any programmer-defined exception class.","source":"slide 21","study":"07-exception-handling.md — 5. Defining your own exception class (slides 20–28)","origin":"practice"},{"id":"w07-019","chapter":"w07","topic":"Custom exception classes","type":"mcq","q":"What does this print?\nSystem.out.println(new Exception(\"boom\"));","options":["boom","Exception: boom","java.lang.Exception: boom","java.lang.Exception"],"answer":2,"fixed":false,"why":"println calls toString(), which gives the full class name, a colon and the message. getMessage() alone would print just 'boom'.","source":"verified on JDK 26","study":"07-exception-handling.md — 4. Exception classes and getMessage (slides 15–19, 26)","origin":"practice"},{"id":"w07-020","chapter":"w07","topic":"Checked vs unchecked","type":"mcq","q":"Which of these exceptions is checked?","options":["ArithmeticException","InputMismatchException","NullPointerException","FileNotFoundException"],"answer":3,"fixed":false,"why":"FileNotFoundException is an IOException, hence checked. The other three descend from RuntimeException and are unchecked.","source":"slides 16, 36–37","study":"07-exception-handling.md — 8. Checked vs unchecked (slides 36–37)","origin":"practice"},{"id":"w07-021","chapter":"w07","topic":"Checked vs unchecked","type":"mcq","q":"Which of these is NOT a checked exception?","options":["RuntimeException","IOException","Exception","FileNotFoundException"],"answer":0,"fixed":false,"why":"RuntimeException and its subclasses are unchecked (slide 36, last bullet). Exception itself and the IOException family are checked.","source":"slides 36–37","study":"07-exception-handling.md — 8. Checked vs unchecked (slides 36–37)","origin":"practice"},{"id":"w07-022","chapter":"w07","topic":"Checked vs unchecked","type":"tf","q":"Error and all its descendant classes are unchecked: they are not subject to the Catch or Declare Rule.","options":["True","False"],"answer":0,"fixed":false,"why":"True (slide 36 and the Error triangle on slide 37).","source":"slides 36–37","study":"07-exception-handling.md — 8. Checked vs unchecked (slides 36–37)","origin":"practice"},{"id":"w07-023","chapter":"w07","topic":"Checked vs unchecked","type":"tf","q":"Every descendant class of Exception is a checked exception.","options":["True","False"],"answer":1,"fixed":false,"why":"False. The RuntimeException branch (e.g. ArithmeticException, InputMismatchException) is unchecked. Slide 36's first bullet over-states this; its last bullet and slide 37 show the exception.","source":"slides 36–37 (errata)","study":"07-exception-handling.md — 12. Errata (slides vs. real Java)","origin":"practice"},{"id":"w07-024","chapter":"w07","topic":"Checked vs unchecked","type":"mcq","q":"What is the root class of everything that can be thrown and caught in Java?","options":["Exception","Throwable","Error","RuntimeException"],"answer":1,"fixed":false,"why":"Throwable sits above both Exception and Error (slide 37). Slide 17 calls Exception the root, which ignores the Error branch.","source":"slide 37 (slide 17 errata)","study":"07-exception-handling.md — 8. Checked vs unchecked (slides 36–37)","origin":"practice"},{"id":"w07-025","chapter":"w07","topic":"throws & catch-or-declare","type":"mcq","q":"What happens when this is compiled and m() is called from main?\nstatic void m() {\n    throw new Exception(\"x\");\n}","options":["It prints x","Compile error: unreported exception","It compiles; the program crashes with Exception: x","It compiles and nothing happens"],"answer":1,"fixed":false,"why":"Exception is checked. m() neither catches it nor declares throws Exception, so the Catch or Declare Rule is broken and javac rejects it.","source":"slides 34–36; verified with javac","study":"07-exception-handling.md — 7. throws clause and the Catch-or-Declare rule (slides 32–35, 39)","origin":"practice"},{"id":"w07-026","chapter":"w07","topic":"throws & catch-or-declare","type":"yn","q":"Does this method compile without a throws clause?\nstatic void m() {\n    throw new IllegalStateException(\"bad\");\n}","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. IllegalStateException is a RuntimeException, so it is unchecked and needs no throws clause.","source":"slides 16, 36; verified","study":"07-exception-handling.md — 8. Checked vs unchecked (slides 36–37)","origin":"practice"},{"id":"w07-027","chapter":"w07","topic":"throws & catch-or-declare","type":"yn","q":"Does this compile?\ntry {\n    int x = 1;\n} catch (IOException e) {\n    System.out.println(\"io\");\n}","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. javac reports 'exception IOException is never thrown in body of corresponding try statement'. A checked exception may only be caught if the try block can throw it.","source":"verified with javac","study":"07-exception-handling.md — 7. throws clause and the Catch-or-Declare rule (slides 32–35, 39)","origin":"practice"},{"id":"w07-028","chapter":"w07","topic":"throws & catch-or-declare","type":"mcq","q":"A base class has void read() throws IOException. Which overriding header in a derived class is NOT allowed?","options":["void read()","void read() throws FileNotFoundException","void read() throws IOException","void read() throws Exception"],"answer":3,"fixed":false,"why":"A derived class may keep the same checked exceptions, a subset, or subclasses of them, but may not add broader or new ones. Exception is broader than IOException.","source":"slide 38; verified with javac","study":"07-exception-handling.md — 9. throws clause when overriding (slide 38)","origin":"practice"},{"id":"w07-029","chapter":"w07","topic":"throws & catch-or-declare","type":"tf","q":"If a method throws an exception and does not catch it, the method invocation ends immediately.","options":["True","False"],"answer":0,"fixed":false,"why":"True (slide 33). Control goes straight to the caller; the rest of the method does not run (only a finally block would).","source":"slide 33","study":"07-exception-handling.md — 7. throws clause and the Catch-or-Declare rule (slides 32–35, 39)","origin":"practice"},{"id":"w07-030","chapter":"w07","topic":"throws & catch-or-declare","type":"mcq","q":"main is declared 'throws Exception' and runs the code below. What happens?\nstatic void c() throws Exception {\n    throw new Exception(\"lost\");\n}\nSystem.out.println(\"start\");\nc();\nSystem.out.println(\"end\");","options":["start, then the program ends with an error message naming java.lang.Exception","start end","Compile error","start lost end"],"answer":0,"fixed":false,"why":"Nobody catches the exception, so a console program terminates with 'Exception in thread \"main\" java.lang.Exception: lost' and a stack trace (slide 39). 'end' never prints.","source":"slide 39; verified","study":"07-exception-handling.md — 7. throws clause and the Catch-or-Declare rule (slides 32–35, 39)","origin":"practice"},{"id":"w07-031","chapter":"w07","topic":"Catch order","type":"mcq","q":"What happens with this code?\ntry {\n    new FileReader(\"x.txt\");\n} catch (IOException e) {\n    System.out.println(\"IO\");\n} catch (FileNotFoundException e) {\n    System.out.println(\"FNF\");\n}","options":["Prints IO","Prints FNF","Compile error: FileNotFoundException has already been caught","Prints IO then FNF"],"answer":2,"fixed":false,"why":"FileNotFoundException is a subclass of IOException, so the second catch can never be reached and javac rejects it. Catch the more specific exception first (slide 31).","source":"slide 31; verified with javac","study":"07-exception-handling.md — 6. Multiple catch blocks and catch order (slides 29–31)","origin":"practice"},{"id":"w07-032","chapter":"w07","topic":"Catch order","type":"mcq","q":"What does this print (one value per line)?\ntry {\n    throw new FileNotFoundException(\"f\");\n} catch (FileNotFoundException e) {\n    System.out.println(\"FNF\");\n} catch (IOException e) {\n    System.out.println(\"IO\");\n} finally {\n    System.out.println(\"F\");\n}","options":["FNF F","FNF IO F","IO F","F FNF"],"answer":0,"fixed":false,"why":"Catch blocks are tried in order and only the first match runs, so IO is skipped. finally then prints F.","source":"slides 30–31, 40; verified","study":"07-exception-handling.md — 6. Multiple catch blocks and catch order (slides 29–31)","origin":"practice"},{"id":"w07-033","chapter":"w07","topic":"Catch order","type":"mcq","q":"What does this print?\ntry {\n    int[] a = new int[2];\n    a[2] = 5;\n} catch (ArithmeticException e) {\n    System.out.println(\"A\");\n} catch (RuntimeException e) {\n    System.out.println(\"R\");\n} catch (Exception e) {\n    System.out.println(\"E\");\n}","options":["A","E","R E","R"],"answer":3,"fixed":false,"why":"ArrayIndexOutOfBoundsException is not an ArithmeticException but is a RuntimeException, so the second catch is the first match. Only one catch block ever runs.","source":"slides 30–31; verified","study":"07-exception-handling.md — 6. Multiple catch blocks and catch order (slides 29–31)","origin":"practice"},{"id":"w08-001","chapter":"w08","topic":"Streams & file types","type":"mcq","q":"A stream through which data flows INTO the program is called…","options":["an input stream","an output stream","a binary stream","a buffered stream"],"answer":0,"fixed":false,"why":"Input = into the program (slide 2). Output streams carry data out of the program, e.g. to the screen or a file.","source":"slide 2","study":"08-file-io.md — 1. Streams (slides 2–3)","origin":"practice"},{"id":"w08-002","chapter":"w08","topic":"Streams & file types","type":"tf","q":"Unlike most binary files, Java binary files are platform independent.","options":["True","False"],"answer":0,"fixed":false,"why":"True, slide 5 says exactly this. Most binary files only work on the same kind of computer and language that created them.","source":"slide 5","study":"08-file-io.md — 2. Text files vs binary files (slides 4–5)","origin":"practice"},{"id":"w08-003","chapter":"w08","topic":"Streams & file types","type":"mcq","q":"According to slide 5, what is the main advantage of binary files over text files?","options":["They can be edited in any text editor","They are always smaller than 1 KB","They are more efficient to process","They never throw exceptions"],"answer":2,"fixed":false,"why":"Binary files are more efficient for programs to process. Being readable in an editor is the advantage of text files.","source":"slides 4–5","study":"08-file-io.md — 2. Text files vs binary files (slides 4–5)","origin":"practice"},{"id":"w08-004","chapter":"w08","topic":"Streams & file types","type":"yn","q":"Is System.out an input stream?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. System.out is an output stream connected to the screen; System.in is the input stream connected to the keyboard.","source":"slide 3","study":"08-file-io.md — 1. Streams (slides 2–3)","origin":"practice"},{"id":"w08-005","chapter":"w08","topic":"Writing with PrintWriter","type":"mcq","q":"What does this print? (File.length() gives the size in bytes.)\nPrintWriter pw = new PrintWriter(new FileOutputStream(\"a.txt\"));\npw.println(\"hello\");\nSystem.out.println(new File(\"a.txt\").length());","options":["6","5","0","Compile error"],"answer":2,"fixed":false,"why":"PrintWriter buffers its output; nothing reaches the file until flush() or close(). Without close() the text can be lost entirely, contrary to slide 11's claim.","source":"slide 11 (errata); verified on JDK 26","study":"08-file-io.md — 11. Errata and modern-Java notes","origin":"practice"},{"id":"w08-006","chapter":"w08","topic":"Writing with PrintWriter","type":"mcq","q":"A program opens an EXISTING file with new PrintWriter(new FileOutputStream(\"data.txt\")). What happens to its old contents?","options":["They are kept and new text is added at the end","They are lost","A FileNotFoundException is thrown","They are copied to data.txt.bak"],"answer":1,"fixed":false,"why":"Opening for output (without append) erases the old contents (slide 9). Keeping them needs the append flag true.","source":"slide 9","study":"08-file-io.md — 3. Writing a text file with PrintWriter (slides 6–11, 14)","origin":"practice"},{"id":"w08-007","chapter":"w08","topic":"Writing with PrintWriter","type":"mcq","q":"What happens when this is compiled?\ntry {\n    PrintWriter out = new PrintWriter(new FileOutputStream(\"b.txt\"));\n} catch (FileNotFoundException e) {\n    System.exit(0);\n}\nout.println(\"hi\");","options":["It compiles and writes hi","Compile error: cannot find symbol out","It compiles but throws NullPointerException","Compile error: unreported FileNotFoundException"],"answer":1,"fixed":false,"why":"A try block is a block: out is local to it, so it does not exist on the last line (slide 17). Declare PrintWriter out = null; before the try.","source":"slide 17; verified with javac","study":"08-file-io.md — 5. Pitfall: a try block is a block (slides 10, 17)","origin":"practice"},{"id":"w08-008","chapter":"w08","topic":"Writing with PrintWriter","type":"mcq","q":"Why do the slides write PrintWriter outputStream = null; before the try block, instead of just PrintWriter outputStream;?","options":["null makes the file open faster","null tells Java to append","Without it the compiler reports that the variable might not have been initialized","null prevents FileNotFoundException"],"answer":2,"fixed":false,"why":"The compiler sees a path (through the catch) where the variable is never assigned, so using it later is an error. Initialising to null satisfies the definite-assignment check.","source":"slide 10; verified with javac","study":"08-file-io.md — 5. Pitfall: a try block is a block (slides 10, 17)","origin":"practice"},{"id":"w08-009","chapter":"w08","topic":"Writing with PrintWriter","type":"tf","q":"The suffix .txt in a file name has a special meaning to a Java program.","options":["True","False"],"answer":1,"fixed":false,"why":"False. A file name is just a String following the operating system's rules; Java gives the suffix no meaning (slide 12).","source":"slide 12","study":"08-file-io.md — 3. Writing a text file with PrintWriter (slides 6–11, 14)","origin":"practice"},{"id":"w08-010","chapter":"w08","topic":"Writing with PrintWriter","type":"mcq","q":"Slide 14 says every file used by a program has two names. Which two?","options":["The real OS file name and the name of the stream connected to it","The file name and its extension","The full path and the relative path","The class name and the package name"],"answer":0,"fixed":false,"why":"The OS name (e.g. \"stuff.txt\") is used once to connect; the stream variable name is what the rest of the program uses.","source":"slide 14","study":"08-file-io.md — 3. Writing a text file with PrintWriter (slides 6–11, 14)","origin":"practice"},{"id":"w08-011","chapter":"w08","topic":"Appending","type":"mcq","q":"What does this print?\nPrintWriter o = new PrintWriter(new FileOutputStream(\"log.txt\"));\no.println(\"one\"); o.close();\no = new PrintWriter(new FileOutputStream(\"log.txt\", true));\no.println(\"two\"); o.close();\no = new PrintWriter(new FileOutputStream(\"log.txt\"));\no.println(\"three\"); o.close();\nSystem.out.println(Files.readAllLines(Path.of(\"log.txt\")));","options":["[one, two, three]","[two, three]","[one, two]","[three]"],"answer":3,"fixed":false,"why":"The second open appends, giving one/two, but the third open has no true flag, so it overwrites everything and only three remains.","source":"slides 9, 18; verified","study":"08-file-io.md — 6. Appending (slide 18)","origin":"practice"},{"id":"w08-012","chapter":"w08","topic":"Appending","type":"mcq","q":"Which statement opens notes.txt so that new text is added AFTER the existing text?","options":["new PrintWriter(new FileOutputStream(\"notes.txt\"), true)","new PrintWriter(new FileOutputStream(\"notes.txt\", true))","new PrintWriter(new FileOutputStream(\"notes.txt\"))","new PrintWriter(\"notes.txt\", true)"],"answer":1,"fixed":false,"why":"The true belongs to FileOutputStream (slide 18). Passing true to PrintWriter instead turns on auto-flush, not append; PrintWriter(String, boolean) does not exist.","source":"slide 18; checked against the JDK API","study":"08-file-io.md — 6. Appending (slide 18)","origin":"practice"},{"id":"w08-013","chapter":"w08","topic":"Appending","type":"mcq","q":"x.txt does not exist before this runs. What does it print?\nfor (String s : new String[]{\"a\", \"b\", \"c\"}) {\n    PrintWriter o = new PrintWriter(new FileOutputStream(\"x.txt\", true));\n    o.println(s);\n    o.close();\n}\nSystem.out.println(Files.readAllLines(Path.of(\"x.txt\")).size());","options":["1","0","3","FileNotFoundException"],"answer":2,"fixed":false,"why":"Append mode creates the file if it is missing, then each pass adds one line. Three lines in total.","source":"slides 9, 18; verified","study":"08-file-io.md — 6. Appending (slide 18)","origin":"practice"},{"id":"w08-014","chapter":"w08","topic":"Reading with Scanner","type":"mcq","q":"morestuff.txt holds three lines: 1 2 / 3 4 / Eat my shorts. What does this print?\nScanner in = new Scanner(new FileInputStream(\"morestuff.txt\"));\nint n1 = in.nextInt(), n2 = in.nextInt(), n3 = in.nextInt();\nString line = in.nextLine();\nSystem.out.println(\"[\" + line + \"]\");","options":["[ 4]","[Eat my shorts.]","[4]","[]"],"answer":0,"fixed":false,"why":"After reading 3 the scanner sits right after it on line 2, so nextLine() returns the rest of that line: a space and 4. That is why slide 21 calls nextLine() once just to move to the next line.","source":"slides 21–22; verified","study":"08-file-io.md — 7. Reading a text file with Scanner (slides 19–23)","origin":"practice"},{"id":"w08-015","chapter":"w08","topic":"Reading with Scanner","type":"mcq","q":"Same file (1 2 / 3 4 / Eat my shorts.). What does this print (one value per line)?\nScanner in = new Scanner(new FileInputStream(\"morestuff.txt\"));\nint n1 = in.nextInt(), n2 = in.nextInt(), n3 = in.nextInt();\nin.nextLine();\nSystem.out.println(n1 + \", \" + n2 + \", and \" + n3);\nSystem.out.println(in.nextLine());","options":["1, 2, and 3 4","1, 2, and 4 Eat my shorts.","1, 2, and 3 Eat my shorts.","1, 2, and 3 3 4"],"answer":2,"fixed":false,"why":"This is Display 10.3. The three ints are 1, 2, 3; the throw-away nextLine() eats ' 4'; the next nextLine() returns 'Eat my shorts.'.","source":"slides 20–23; verified","study":"08-file-io.md — 7. Reading a text file with Scanner (slides 19–23)","origin":"practice"},{"id":"w08-016","chapter":"w08","topic":"Reading with Scanner","type":"mcq","q":"data.txt exists and contains 42. What does this print?\nScanner in = new Scanner(\"data.txt\");\nSystem.out.println(in.next());","options":["42","FileNotFoundException","Compile error","data.txt"],"answer":3,"fixed":false,"why":"Scanner(String) scans the string itself, not a file of that name. Use new Scanner(new File(\"data.txt\")) or new Scanner(new FileInputStream(\"data.txt\")).","source":"slide 19/25 (errata); verified","study":"08-file-io.md — 11. Errata and modern-Java notes","origin":"practice"},{"id":"w08-017","chapter":"w08","topic":"Reading with Scanner","type":"mcq","q":"nums.txt holds 3 4 5 on line 1 and 10 on line 2. What does this print?\nScanner in = new Scanner(new File(\"nums.txt\"));\nint t = 0;\nwhile (in.hasNextInt()) t += in.nextInt();\nSystem.out.println(t);","options":["12","22","10","3"],"answer":1,"fixed":false,"why":"hasNextInt() ignores line breaks, so all four numbers are added: 3+4+5+10 = 22.","source":"slide 19 (Scanner methods behave the same on files); verified","study":"08-file-io.md — 7. Reading a text file with Scanner (slides 19–23)","origin":"practice"},{"id":"w08-018","chapter":"w08","topic":"Reading with Scanner","type":"mcq","q":"A Scanner has read every token of a file. What does one more call to nextInt() do?","options":["Returns 0","Returns -1","Throws NoSuchElementException","Throws FileNotFoundException"],"answer":2,"fixed":false,"why":"Reading past the end throws the unchecked NoSuchElementException (slide 16). Returning -1 at the end is BufferedReader.read()'s behaviour.","source":"slide 16; verified","study":"08-file-io.md — 4. IOException and friends (slides 15–16)","origin":"practice"},{"id":"w08-019","chapter":"w08","topic":"Reading with BufferedReader","type":"mcq","q":"d.txt contains 42. What does this print?\nBufferedReader br = new BufferedReader(new FileReader(\"d.txt\"));\nSystem.out.println(br.read() + \" \" + (char) br.read());","options":["4 2","52 50","4 50","52 2"],"answer":3,"fixed":false,"why":"read() returns the character code as an int: '4' is 52. Only the second call is cast to char, so it prints 2 (slide 26).","source":"slide 26; verified","study":"08-file-io.md — 8. Reading a text file with BufferedReader (slides 24–31)","origin":"practice"},{"id":"w08-020","chapter":"w08","topic":"Reading with BufferedReader","type":"mcq","q":"What does BufferedReader's readLine() return when it tries to read beyond the end of the file?","options":["-1","null","an empty string","it throws EOFException"],"answer":1,"fixed":false,"why":"readLine() returns null at end of file (slide 31). -1 is what read() returns.","source":"slide 31","study":"08-file-io.md — 8. Reading a text file with BufferedReader (slides 24–31)","origin":"practice"},{"id":"w08-021","chapter":"w08","topic":"Reading with BufferedReader","type":"mcq","q":"What does BufferedReader's read() return when it tries to read beyond the end of the file?","options":["-1","null","0","'\\0'"],"answer":0,"fixed":false,"why":"read() returns an int, and -1 signals end of file (slide 31). null is the end marker for readLine().","source":"slide 31","study":"08-file-io.md — 8. Reading a text file with BufferedReader (slides 24–31)","origin":"practice"},{"id":"w08-022","chapter":"w08","topic":"Reading with BufferedReader","type":"mcq","q":"morestuff2.txt holds 1 2 3 / Jack jump over / the candle stick. What does this print?\nBufferedReader in = new BufferedReader(new FileReader(\"morestuff2.txt\"));\nString line = in.readLine();\nline = in.readLine();\nSystem.out.println(line);\nin.close();","options":["1 2 3","the candle stick.","Jack jump over","Jack"],"answer":2,"fixed":false,"why":"Each readLine() returns one whole line; the second call gives the second line (Display 10.7 output on slide 29).","source":"slides 27–29; verified","study":"08-file-io.md — 8. Reading a text file with BufferedReader (slides 24–31)","origin":"practice"},{"id":"w08-023","chapter":"w08","topic":"Reading with BufferedReader","type":"mcq","q":"How does a program read an int from a text file with BufferedReader?","options":["readInt()","nextInt()","read() then cast to int","readLine(), then Integer.parseInt"],"answer":3,"fixed":false,"why":"BufferedReader has no number methods (slide 30): read the line as a String and convert it with a wrapper class. nextInt() belongs to Scanner.","source":"slide 30","study":"08-file-io.md — 8. Reading a text file with BufferedReader (slides 24–31)","origin":"practice"},{"id":"w08-024","chapter":"w08","topic":"Reading with BufferedReader","type":"mcq","q":"Why does Display 10.7 need both catch (FileNotFoundException e) and catch (IOException e)?","options":["FileReader may throw FileNotFoundException and readLine() may throw IOException","Java requires every try to have two catches","IOException is unchecked","FileNotFoundException is a superclass of IOException"],"answer":0,"fixed":false,"why":"Opening can fail with FileNotFoundException; reading can fail with IOException. FileNotFoundException is the subclass, so it must be caught first.","source":"slide 28","study":"08-file-io.md — 8. Reading a text file with BufferedReader (slides 24–31)","origin":"practice"},{"id":"w08-025","chapter":"w08","topic":"I/O exceptions & paths","type":"mcq","q":"When a program opens a file for OUTPUT and gets a FileNotFoundException, what does it really mean?","options":["The file already exists","The file could not be created","The file is empty","The disk is full of text files"],"answer":1,"fixed":false,"why":"Slide 10: for output it actually means the file could not be created, e.g. because the folder does not exist.","source":"slide 10","study":"08-file-io.md — 3. Writing a text file with PrintWriter (slides 6–11, 14)","origin":"practice"},{"id":"w08-026","chapter":"w08","topic":"I/O exceptions & paths","type":"mcq","q":"The folder nodir does not exist. What does this print?\ntry {\n    new PrintWriter(new FileOutputStream(\"nodir/x.txt\"));\n    System.out.println(\"opened\");\n} catch (FileNotFoundException e) {\n    System.out.println(\"FNF\");\n}","options":["opened","FNF","opened FNF","Nothing; Java creates the folder"],"answer":1,"fixed":false,"why":"Java does not create missing folders, so the file cannot be created and FileNotFoundException is thrown before 'opened'.","source":"slide 10; verified","study":"08-file-io.md — 3. Writing a text file with PrintWriter (slides 6–11, 14)","origin":"practice"},{"id":"w08-027","chapter":"w08","topic":"I/O exceptions & paths","type":"mcq","q":"Which Java string literal correctly names the Windows file C:\\dataFiles\\goodData\\data.txt?","options":["\"C:\\dataFiles\\goodData\\data.txt\"","'C:\\dataFiles\\goodData\\data.txt'","C:\\\\dataFiles\\\\goodData\\\\data.txt","\"C:\\\\dataFiles\\\\goodData\\\\data.txt\""],"answer":3,"fixed":false,"why":"Inside a string literal a single backslash starts an escape sequence, so each one is doubled (slide 35). Single quotes are for char literals.","source":"slide 35","study":"08-file-io.md — 10. Path names (slides 32–35)","origin":"practice"},{"id":"w08-028","chapter":"w08","topic":"I/O exceptions & paths","type":"mcq","q":"How many characters does this string hold? What is printed?\nSystem.out.println(\"C:\\\\data\\\\a.txt\".length());","options":["13","15","11","12"],"answer":0,"fixed":false,"why":"Each \\\\ in the source is ONE backslash character, so the string is C:\\data\\a.txt, 13 characters.","source":"slide 35; verified","study":"08-file-io.md — 10. Path names (slides 32–35)","origin":"practice"},{"id":"w08-029","chapter":"w08","topic":"I/O exceptions & paths","type":"mcq","q":"Which of these exceptions must be caught or declared?","options":["NoSuchElementException","InputMismatchException","IOException","IllegalStateException"],"answer":2,"fixed":false,"why":"IOException and its subclasses are checked (slide 15). The other three are the unchecked Scanner exceptions from slide 16.","source":"slides 15–16","study":"08-file-io.md — 4. IOException and friends (slides 15–16)","origin":"practice"},{"id":"w08-030","chapter":"w08","topic":"I/O exceptions & paths","type":"yn","q":"Must the statement new BufferedReader(new FileReader(\"x.txt\")) be inside a try block (or in a method with a throws clause)?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. The FileReader constructor throws FileNotFoundException, a checked exception, so the Catch or Declare Rule applies.","source":"slides 15, 24–25; verified with javac","study":"08-file-io.md — 4. IOException and friends (slides 15–16)","origin":"practice"},{"id":"w08-031","chapter":"w08","topic":"I/O exceptions & paths","type":"mcq","q":"A plain file name such as \"data.txt\" (no path) refers to a file in which folder?","options":["The user's home folder","The root directory","The Java installation folder","The folder in which the program is run"],"answer":3,"fixed":false,"why":"Slide 32: without a path, the file is assumed to be in the directory where the program is run. Otherwise give a full or relative path.","source":"slide 32","study":"08-file-io.md — 10. Path names (slides 32–35)","origin":"practice"}]};
